export const BODY = {"level-8":{"id":"level-8","kind":"level","level":8,"src":"level:8","title":"Level 8 · Powers and Proofs","body":"Vedic multiplying, digit roots and counting factors, the index laws, sets and Venn diagrams, constructions and Pythagoras, and permutations and combinations.","route":"#/atlas","cta":"See the road"},"land-l8-muldiv":{"id":"land-l8-muldiv","kind":"land","level":8,"src":"land:l8-muldiv","title":"Vedic multiplying — in The Sutra Observatory","body":"4 stops on this stretch of the road: Near ten: the cross · Near a hundred · Just above a hundred · Vertically and crosswise.","art":"art/w-observatory.webp","route":"#/world/observatory","cta":"Visit Observatory"},"land-l8-factors":{"id":"land-l8-factors","kind":"land","level":8,"src":"land:l8-factors","title":"Kinds of number and factors — in The Prime Quarry","body":"5 stops on this stretch of the road: Number families · Coprime: no stone shared · Counting factors from the stones · The nines check · Divisible by 3 or 9?.","art":"art/w-quarry.webp","route":"#/world/quarry","cta":"Visit Quarry"},"land-l8-powers":{"id":"land-l8-powers","kind":"land","level":8,"src":"land:l8-powers","title":"Index laws and squares — in The Square Palace","body":"4 stops on this stretch of the road: The odd-number staircase · Squares near fifty · The index laws · Around a middle number.","art":"art/w-palace.webp","route":"#/world/palace","cta":"Visit Palace"},"land-l8-sets":{"id":"land-l8-sets","kind":"land","level":8,"src":"land:l8-sets","title":"Sets and Venn diagrams — in Set Island","body":"6 stops on this stretch of the road: In the set, or not? · Counting a set — and the empty set · Union and intersection · Venn diagrams that count · How many subsets? · Who won which prize?.","art":"art/w-setisland.webp","route":"#/world/setisland","cta":"Visit Set Island"},"land-l8-shape":{"id":"land-l8-shape","kind":"land","level":8,"src":"land:l8-shape","title":"Constructions and Pythagoras — in Shape City","body":"3 stops on this stretch of the road: The perpendicular bisector · The angle bisector · Pythagoras’ theorem.","art":"art/w-shapecity.webp","route":"#/world/shapecity","cta":"Visit Shape City"},"land-l8-data":{"id":"land-l8-data","kind":"land","level":8,"src":"land:l8-data","title":"Orders and choices — in The Data Carnival","body":"3 stops on this stretch of the road: Putting things in order · Permutations: order matters · Combinations: order doesn't matter.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"trick-perpendicular-bisector-idea":{"id":"trick-perpendicular-bisector-idea","kind":"trick","src":"stop:perpendicular-bisector#idea","title":"The perpendicular bisector","body":"Every point the same distance from A and B lies on one straight line: through the middle of AB, at right angles to it. Equal compass arcs from A and B find it. Open the compasses to more than half of AB. Swing an arc from A, then — without changing the compasses — one from B. The arcs cross at two points, one above AB and one below. Each crossing is one compass-width from A and one compass-width from B, so each is the same distance from both.","cta":"Learn the trick","level":8,"route":"#/stop/perpendicular-bisector"},"story-perpendicular-bisector-open":{"id":"story-perpendicular-bisector-open","kind":"story","src":"story:perpendicular-bisector#open","badge":{"id":"story","label":"A story"},"title":"The bird bath","body":"On Nova’s garden plan, two lemon trees stand at (2, 1) and (10, 1). She wants a bird bath exactly as far from one tree as from the other. — with Nova and Theo.","art":"art/s-garden.webp","cta":"Read the story","level":8,"route":"#/stop/perpendicular-bisector"},"hook-perpendicular-bisector-hook":{"id":"hook-perpendicular-bisector-hook","kind":"hook","src":"stop:perpendicular-bisector#hook","title":"Can you? — The perpendicular bisector","body":"Two friends live at A and B. Where could you stand to be exactly as far from one as from the other — and how many such places are there?","cta":"Find out how","level":8,"route":"#/stop/perpendicular-bisector"},"idea-perpendicular-bisector-case0":{"id":"idea-perpendicular-bisector-case0","kind":"idea","src":"stop:perpendicular-bisector#case0","title":"The perpendicular bisector: A and B side by side","body":"A and B are on the same row, so the bisector stands straight up through the middle: x = halfway between their across numbers.","cta":"See it worked","level":8,"route":"#/stop/perpendicular-bisector"},"worked-perpendicular-bisector-worked0":{"id":"worked-perpendicular-bisector-worked0","kind":"worked","src":"stop:perpendicular-bisector#worked0","title":"Worked out — The perpendicular bisector: A and B side by side","body":"A is (2, 1) and B is (10, 1). Their perpendicular bisector is the line x = ?. What is the missing number?: Halfway across from x = 2 to x = 10: (2 + 10) ÷ 2 → 6 · AB runs across, so the bisector runs straight up through its middle: x = → 6","cta":"Watch it step by step","level":8,"route":"#/stop/perpendicular-bisector"},"idea-perpendicular-bisector-case1":{"id":"idea-perpendicular-bisector-case1","kind":"idea","src":"stop:perpendicular-bisector#case1","title":"The perpendicular bisector: A and B one above other","body":"A and B are in the same column, so the bisector lies flat through the middle: y = halfway between their up numbers.","cta":"See it worked","level":8,"route":"#/stop/perpendicular-bisector"},"worked-perpendicular-bisector-worked1":{"id":"worked-perpendicular-bisector-worked1","kind":"worked","src":"stop:perpendicular-bisector#worked1","title":"Worked out — The perpendicular bisector: A and B one above other","body":"A is (3, 2) and B is (3, 8). Their perpendicular bisector is the line y = ?. What is the missing number?: Halfway up from y = 2 to y = 8: (2 + 8) ÷ 2 → 5 · AB runs up, so the bisector runs straight across through its middle: y = → 5","cta":"Watch it step by step","level":8,"route":"#/stop/perpendicular-bisector"},"idea-perpendicular-bisector-case2":{"id":"idea-perpendicular-bisector-case2","kind":"idea","src":"stop:perpendicular-bisector#case2","title":"The perpendicular bisector: Pick a point: straight AB","body":"The bisector is the upright line through the middle of AB. The right point sits exactly on it — every other one is off to a side.","cta":"See it worked","level":8,"route":"#/stop/perpendicular-bisector"},"worked-perpendicular-bisector-worked2":{"id":"worked-perpendicular-bisector-worked2","kind":"worked","src":"stop:perpendicular-bisector#worked2","title":"Worked out — The perpendicular bisector: Pick a point: straight AB","body":"A is (2, 4) and B is (8, 4). Which point is the same distance from A as from B — so it lies on the perpendicular bisector of AB?: The middle of AB — its x: (2 + 8) ÷ 2 → 5 · Its y: (4 + 4) ÷ 2 → 4 · The bisector goes through that middle, square to AB. Which point is on it? (Check: across² + up² to A and to B must match.) → (5, 7)","cta":"Watch it step by step","level":8,"route":"#/stop/perpendicular-bisector"},"idea-perpendicular-bisector-case3":{"id":"idea-perpendicular-bisector-case3","kind":"idea","src":"stop:perpendicular-bisector#case3","title":"The perpendicular bisector: Pick a point: slanted AB","body":"With a slanted AB the bisector slants too, so check each point: across² + up² to A must equal across² + up² to B.","cta":"See it worked","level":8,"route":"#/stop/perpendicular-bisector"},"why-perpendicular-bisector-why1":{"id":"why-perpendicular-bisector-why1","kind":"why","src":"stop:perpendicular-bisector#why1","title":"Why “The perpendicular bisector” works","body":"Join the two crossings. Now look at the four points A, the top crossing, B and the bottom crossing: all four sides between them are one compass-width, so they make a rhombus. The diagonals of a rhombus always cut each other in half at right angles. So the line you drew passes through the exact middle of AB, square to it: it bisects AB (cuts it in half) and is perpendicular to it.","cta":"See why","level":8,"route":"#/stop/perpendicular-bisector"},"why-perpendicular-bisector-why2":{"id":"why-perpendicular-bisector-why2","kind":"why","src":"stop:perpendicular-bisector#why2","title":"Why “The perpendicular bisector” works","body":"Fold the paper along that line and A lands exactly on B, so every point on the fold is as far from A as from B — there are endlessly many such places, all on one line. On a grid you can check a point without compasses: square its across-distance and its up-distance to A and add them, do the same for B, and see if the totals match. When A and B sit on the same row, the bisector is the upright line x = the halfway number; when they sit in the same column, it is the flat line y = the halfway number.","cta":"See why","level":8,"route":"#/stop/perpendicular-bisector"},"algebra-perpendicular-bisector-alg":{"id":"algebra-perpendicular-bisector-alg","kind":"algebra","src":"stop:perpendicular-bisector#alg","title":"The algebra behind “The perpendicular bisector”","body":"P on the bisector ⇔ PA = PB ⇔ (x − x₁)² + (y − y₁)² = (x − x₂)² + (y − y₂)²","cta":"See why","level":8,"route":"#/stop/perpendicular-bisector"},"moment-perpendicular-bisector-beat1":{"id":"moment-perpendicular-bisector-beat1","kind":"moment","src":"story:perpendicular-bisector#beat1","badge":{"id":"story","label":"A story"},"title":"The bird bath — on the notepad","body":"Nova: Halfway between them works: 4 from each. 8 ÷ 2 = 4","cta":"Read the story","level":8,"route":"#/stop/perpendicular-bisector"},"moral-perpendicular-bisector-beat6":{"id":"moral-perpendicular-bisector-beat6","kind":"moral","src":"story:perpendicular-bisector#beat6","badge":{"id":"story","label":"A story"},"title":"Theo, in “The bird bath”","body":"The line through the middle is x = 6.","cta":"Read the story","level":8,"route":"#/stop/perpendicular-bisector"},"try-perpendicular-bisector-L8":{"id":"try-perpendicular-bisector-L8","kind":"try","level":8,"src":"try:perpendicular-bisector@8/1#0","title":"The perpendicular bisector — your turn","route":"#/stop/perpendicular-bisector","cta":"Practise this stop","play":{"q":"A is (4, 2) and B is (8, 2). Their perpendicular bisector is the line x = ?. What is the missing number?","opts":["6","7","5"],"after":"Every point the same distance from A and B lies on one straight line: through the middle of AB, at right angles to it. Equal compass arcs from A and B find it."}},"trick-angle-bisector-idea":{"id":"trick-angle-bisector-idea","kind":"trick","src":"stop:angle-bisector#idea","title":"The angle bisector","body":"The angle bisector cuts an angle into two equal halves, and every point on it is the same distance from both arms. Put the compass point on the corner and swing one arc that cuts both arms, at M and N. Now, from M and from N, swing two arcs of the same size so they cross at P. Draw the line from the corner through P. That line is the bisector.","cta":"Learn the trick","level":8,"route":"#/stop/angle-bisector"},"story-angle-bisector-open":{"id":"story-angle-bisector-open","kind":"story","src":"story:angle-bisector#open","badge":{"id":"story","label":"A story"},"title":"The corner path","body":"Two walls of a city park meet at a corner of 84°. Suki wants a path from the corner that splits it into two equal angles. — with Suki and Rafi.","art":"art/s-city.webp","cta":"Read the story","level":8,"route":"#/stop/angle-bisector"},"hook-angle-bisector-hook":{"id":"hook-angle-bisector-hook","kind":"hook","src":"stop:angle-bisector#hook","title":"Can you? — The angle bisector","body":"A path must split a corner of 84° into two equal angles. Where does it go — with compasses, and no protractor?","cta":"Find out how","level":8,"route":"#/stop/angle-bisector"},"idea-angle-bisector-case0":{"id":"idea-angle-bisector-case0","kind":"idea","src":"stop:angle-bisector#case0","title":"The angle bisector: Each half","body":"The bisector cuts the angle into two equal halves, so each half is the whole angle ÷ 2.","cta":"See it worked","level":8,"route":"#/stop/angle-bisector"},"worked-angle-bisector-worked0":{"id":"worked-angle-bisector-worked0","kind":"worked","src":"stop:angle-bisector#worked0","title":"Worked out — The angle bisector: Each half","body":"An angle of 84° is cut in two by its bisector. How big is each half, in degrees?: The whole angle → 84 · Two equal halves: 84 ÷ 2 → 42","cta":"Watch it step by step","level":8,"route":"#/stop/angle-bisector"},"idea-angle-bisector-case1":{"id":"idea-angle-bisector-case1","kind":"idea","src":"stop:angle-bisector#case1","title":"The angle bisector: The whole angle","body":"Backwards: you are given one half. The other half is the same size, so the whole angle is double.","cta":"See it worked","level":8,"route":"#/stop/angle-bisector"},"worked-angle-bisector-worked1":{"id":"worked-angle-bisector-worked1","kind":"worked","src":"stop:angle-bisector#worked1","title":"Worked out — The angle bisector: The whole angle","body":"The bisector of an angle makes 35° with one arm. How big is the whole angle, in degrees?: One half → 35 · The other half is the same size → 35 · Both halves together → 70","cta":"Watch it step by step","level":8,"route":"#/stop/angle-bisector"},"idea-angle-bisector-case2":{"id":"idea-angle-bisector-case2","kind":"idea","src":"stop:angle-bisector#case2","title":"The angle bisector: Where bisectors meet","body":"Halve angles B and C first, then use triangle IBC: its three angles make 180°, so angle BIC is whatever is left.","cta":"See it worked","level":8,"route":"#/stop/angle-bisector"},"worked-angle-bisector-worked2":{"id":"worked-angle-bisector-worked2","kind":"worked","src":"stop:angle-bisector#worked2","title":"Worked out — The angle bisector: Where bisectors meet","body":"In triangle ABC, angle B is 70° and angle C is 50°. The bisectors of angles B and C meet at I. How big is angle BIC, in degrees?: The bisector halves angle B: 70 ÷ 2 → 35 · And angle C: 50 ÷ 2 → 25 · Triangle IBC has 180° altogether: 180 − 35 − 25 → 120","cta":"Watch it step by step","level":8,"route":"#/stop/angle-bisector"},"why-angle-bisector-why1":{"id":"why-angle-bisector-why1","kind":"why","src":"stop:angle-bisector#why1","title":"Why “The angle bisector” works","body":"Why are the two halves equal? Look at the two triangles corner–M–P and corner–N–P. The corner is the same distance from M and from N (one arc). P is the same distance from M and from N (two equal arcs). And the side from the corner to P is shared. Three sides the same means the triangles are the same triangle, just flipped — so the two angles at the corner match.","cta":"See why","level":8,"route":"#/stop/angle-bisector"},"why-angle-bisector-why2":{"id":"why-angle-bisector-why2","kind":"why","src":"stop:angle-bisector#why2","title":"Why “The angle bisector” works","body":"Fold along the bisector and one arm lands on the other, so every point on it is the same distance from both arms. In a triangle the three bisectors meet at one point, the same distance from all three sides — the centre of the biggest circle that fits inside. And since each bisector takes exactly half of its angle, halving then using the 180° of a triangle finds the angles there.","cta":"See why","level":8,"route":"#/stop/angle-bisector"},"algebra-angle-bisector-alg":{"id":"algebra-angle-bisector-alg","kind":"algebra","src":"stop:angle-bisector#alg","title":"The algebra behind “The angle bisector”","body":"each half = θ ÷ 2 · in triangle ABC, the bisectors of B and C meet at I: ∠BIC = 180° − B/2 − C/2","cta":"See why","level":8,"route":"#/stop/angle-bisector"},"moment-angle-bisector-beat5":{"id":"moment-angle-bisector-beat5","kind":"moment","src":"story:angle-bisector#beat5","badge":{"id":"story","label":"A story"},"title":"The corner path — on the notepad","body":"Rafi: Check it: two halves make the whole corner. 42 × 2 = 84","cta":"Read the story","level":8,"route":"#/stop/angle-bisector"},"moral-angle-bisector-beat6":{"id":"moral-angle-bisector-beat6","kind":"moral","src":"story:angle-bisector#beat6","badge":{"id":"story","label":"A story"},"title":"Suki, in “The corner path”","body":"Each half is 42°. The path is the angle bisector.","cta":"Read the story","level":8,"route":"#/stop/angle-bisector"},"try-angle-bisector-L8":{"id":"try-angle-bisector-L8","kind":"try","level":8,"src":"try:angle-bisector@8/1#0","title":"The angle bisector — your turn","route":"#/stop/angle-bisector","cta":"Practise this stop","play":{"q":"An angle of 120° is cut in two by its bisector. How big is each half, in degrees?","opts":["60","120","61"],"after":"The angle bisector cuts an angle into two equal halves, and every point on it is the same distance from both arms."}},"trick-number-families-idea":{"id":"trick-number-families-idea","kind":"trick","src":"stop:number-families#idea","title":"Number families","body":"Ask three questions in order: is it a whole amount? Is it below zero? Is it zero? The answers say which family it belongs to. The counting numbers are the ones you count with: 1, 2, 3, and on for ever. Add zero — the number of sweets in an empty jar — and you have the whole numbers. Add the numbers below zero too, like −4 °C on a cold morning, and you have the integers. (Some books call the counting numbers \"natural numbers\". Books do not all agree on the names, so this Quarry says which one it means.)","cta":"Learn the trick","level":8,"route":"#/stop/number-families"},"story-number-families-open":{"id":"story-number-families-open","kind":"story","src":"story:number-families#open","badge":{"id":"story","label":"A story"},"title":"Hoops by the pond","body":"On a frosty morning the thermometer by the pond reads −4 °C. Pip and Nova chalk three hoops, one inside another, on the path. — with Pip and Nova.","art":"art/s-pond.webp","cta":"Read the story","level":8,"route":"#/stop/number-families"},"hook-number-families-hook":{"id":"hook-number-families-hook","kind":"hook","src":"stop:number-families#hook","title":"Can you? — Number families","body":"−4, 0 and 7 — are they all the same kind of number?","cta":"Find out how","level":8,"route":"#/stop/number-families"},"idea-number-families-case0":{"id":"idea-number-families-case0","kind":"idea","src":"stop:number-families#case0","title":"Number families: Counting number","body":"A whole amount above zero is a counting number — the smallest hoop, and it sits inside the other two as well.","cta":"See it worked","level":8,"route":"#/stop/number-families"},"worked-number-families-worked0":{"id":"worked-number-families-worked0","kind":"worked","src":"stop:number-families#worked0","title":"Worked out — Number families: Counting number","body":"What is the smallest family 7 belongs to?: Is 7 a whole amount, with nothing after the point? → Yes · Is it below zero? → No · Is it zero? → No · So the smallest family is → counting number","cta":"Watch it step by step","level":8,"route":"#/stop/number-families"},"idea-number-families-case1":{"id":"idea-number-families-case1","kind":"idea","src":"stop:number-families#case1","title":"Number families: Whole number","body":"Zero is a whole amount — an empty jar — but you never start counting at zero, so its smallest hoop is the whole numbers.","cta":"See it worked","level":8,"route":"#/stop/number-families"},"idea-number-families-case2":{"id":"idea-number-families-case2","kind":"idea","src":"stop:number-families#case2","title":"Number families: Integer","body":"Work the sum out first. 7 − 12 lands below zero, so it is only in the biggest hoop, the integers.","cta":"See it worked","level":8,"route":"#/stop/number-families"},"worked-number-families-worked2":{"id":"worked-number-families-worked2","kind":"worked","src":"stop:number-families#worked2","title":"Worked out — Number families: Integer","body":"What is the smallest family the answer to 7 − 12 belongs to?: Work it out: 7 − 12 → -5 · Is it below zero? → Yes · So the smallest family is → integer","cta":"Watch it step by step","level":8,"route":"#/stop/number-families"},"idea-number-families-case3":{"id":"idea-number-families-case3","kind":"idea","src":"stop:number-families#case3","title":"Number families: Not an integer","body":"A part left over — 7 ÷ 2 is three and a half — puts a number outside all three hoops. It is still a real number.","cta":"See it worked","level":8,"route":"#/stop/number-families"},"worked-number-families-worked3":{"id":"worked-number-families-worked3","kind":"worked","src":"stop:number-families#worked3","title":"Worked out — Number families: Not an integer","body":"What is the smallest family the answer to 7 ÷ 2 belongs to?: Does 7 ÷ 2 come out exactly, with nothing left over? → No · So which family? → not an integer","cta":"Watch it step by step","level":8,"route":"#/stop/number-families"},"why-number-families-why1":{"id":"why-number-families-why1","kind":"why","src":"stop:number-families#why1","title":"Why “Number families” works","body":"The families sit one inside the next, like hoops. 7 is a counting number, so it is also a whole number and an integer. 0 is not a counting number — you never start counting with \"zero\" — but it is whole. −4 is only an integer. So the useful question is the SMALLEST hoop a number fits in.","cta":"See why","level":8,"route":"#/stop/number-families"},"why-number-families-why2":{"id":"why-number-families-why2","kind":"why","src":"stop:number-families#why2","title":"Why “Number families” works","body":"A number with a part left over — 3.5, or 7 ÷ 2 — is in none of these hoops. It is still a perfectly good number, just not an integer. Sums can move a number between families: 7 − 12 starts with two counting numbers and lands outside that hoop, below zero.","cta":"See why","level":8,"route":"#/stop/number-families"},"algebra-number-families-alg":{"id":"algebra-number-families-alg","kind":"algebra","src":"stop:number-families#alg","title":"The algebra behind “Number families”","body":"counting {1, 2, 3, …} ⊂ whole {0, 1, 2, …} ⊂ integers {…, −2, −1, 0, 1, 2, …}","cta":"See why","level":8,"route":"#/stop/number-families"},"moral-number-families-beat5":{"id":"moral-number-families-beat5","kind":"moral","src":"story:number-families#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Hoops by the pond”","body":"So 7 is in all three hoops, 0 in two, and −4 only in the big one!","cta":"Read the story","level":8,"route":"#/stop/number-families"},"try-number-families-L8":{"id":"try-number-families-L8","kind":"try","level":8,"src":"try:number-families@8/2#0","title":"Number families — your turn","route":"#/stop/number-families","cta":"Practise this stop","play":{"q":"What is the smallest family 87 belongs to?","opts":["counting number","whole number","integer"],"after":"Ask three questions in order: is it a whole amount? Is it below zero? Is it zero? The answers say which family it belongs to."}},"trick-coprime-idea":{"id":"trick-coprime-idea","kind":"trick","src":"stop:coprime#idea","title":"Coprime: no stone shared","body":"Take the prime stones of the first number and test each one on the second. If none goes in, the two numbers are coprime. Two numbers are coprime when they share no prime stone at all, so the only number that divides both is 1. 35 is 5 × 7; 48 is 2 × 2 × 2 × 2 × 3. No stone appears in both, so 35 and 48 are coprime — even though neither of them is prime.","cta":"Learn the trick","level":8,"route":"#/stop/coprime"},"story-coprime-open":{"id":"story-coprime-open","kind":"story","src":"story:coprime#open","badge":{"id":"story","label":"A story"},"title":"The painted cogs","body":"At the fair, a machine has two cogs: one with 35 teeth, one with 48. A tooth on each is painted red, and the red teeth touch. — with Ines and Mira.","art":"art/s-fair.webp","cta":"Read the story","level":8,"route":"#/stop/coprime"},"hook-coprime-hook":{"id":"hook-coprime-hook","kind":"hook","src":"stop:coprime#hook","title":"Can you? — Coprime: no stone shared","body":"35 and 48 — do they have any prime stone in common?","cta":"Find out how","level":8,"route":"#/stop/coprime"},"idea-coprime-case0":{"id":"idea-coprime-case0","kind":"idea","src":"stop:coprime#case0","title":"Coprime: no stone shared: Coprime","body":"Try EVERY stone of the first number on the second. Only when none of them goes in are the two coprime.","cta":"See it worked","level":8,"route":"#/stop/coprime"},"worked-coprime-worked0":{"id":"worked-coprime-worked0","kind":"worked","src":"stop:coprime#worked0","title":"Worked out — Coprime: no stone shared: Coprime","body":"Are 35 and 48 coprime?: 35 = 5 × 7. Does 5 go into 48? → No · Does 7 go into 48? → No · No stone shared. Coprime? → Yes","cta":"Watch it step by step","level":8,"route":"#/stop/coprime"},"idea-coprime-case1":{"id":"idea-coprime-case1","kind":"idea","src":"stop:coprime#case1","title":"Coprime: no stone shared: Not coprime","body":"You can stop at the first stone that goes in. 21 = 3 × 7: 3 does not go into 35, but 7 does — they share a stone.","cta":"See it worked","level":8,"route":"#/stop/coprime"},"worked-coprime-worked1":{"id":"worked-coprime-worked1","kind":"worked","src":"stop:coprime#worked1","title":"Worked out — Coprime: no stone shared: Not coprime","body":"Are 21 and 35 coprime?: 21 = 3 × 7. Does 3 go into 35? → No · Does 7 go into 35? → Yes · They share the stone 7. Coprime? → No","cta":"Watch it step by step","level":8,"route":"#/stop/coprime"},"why-coprime-why1":{"id":"why-coprime-why1","kind":"why","src":"stop:coprime#why1","title":"Why “Coprime: no stone shared” works","body":"You do not need both lists of stones. Any number that divides both would be built from stones of the first, so it is enough to test the first number's stones on the second. If 5 does not go into 48 and 7 does not either, nothing built from them can.","cta":"See why","level":8,"route":"#/stop/coprime"},"why-coprime-why2":{"id":"why-coprime-why2","kind":"why","src":"stop:coprime#why2","title":"Why “Coprime: no stone shared” works","body":"Coprime numbers are why a fraction like 35/48 cannot be simplified, and why two cogs with 35 and 48 teeth take a long time to line up again: sharing nothing, they only meet after 35 × 48 teeth have gone by.","cta":"See why","level":8,"route":"#/stop/coprime"},"algebra-coprime-alg":{"id":"algebra-coprime-alg","kind":"algebra","src":"stop:coprime#alg","title":"The algebra behind “Coprime: no stone shared”","body":"a, b coprime ⇔ HCF(a, b) = 1 ⇔ no prime p divides both","cta":"See why","level":8,"route":"#/stop/coprime"},"moment-coprime-beat3":{"id":"moment-coprime-beat3","kind":"moment","src":"story:coprime#beat3","badge":{"id":"story","label":"A story"},"title":"The painted cogs — on the notepad","body":"Mira: And 48 is 2 × 2 × 2 × 2 × 3. Does 5 go into 48? No. Does 7? No. 2 × 2 × 2 × 2 × 3 = 48","cta":"Read the story","level":8,"route":"#/stop/coprime"},"moral-coprime-beat5":{"id":"moral-coprime-beat5","kind":"moral","src":"story:coprime#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “The painted cogs”","body":"So the red teeth only meet again after 35 × 48 teeth go by. Every tooth meets every tooth first.","cta":"Read the story","level":8,"route":"#/stop/coprime"},"try-coprime-L8":{"id":"try-coprime-L8","kind":"try","level":8,"src":"try:coprime@8/1#0","title":"Coprime: no stone shared — your turn","route":"#/stop/coprime","cta":"Practise this stop","play":{"q":"Are 4 and 22 coprime?","opts":["No","Yes"],"after":"Take the prime stones of the first number and test each one on the second. If none goes in, the two numbers are coprime."}},"trick-factor-count-stones-idea":{"id":"trick-factor-count-stones-idea","kind":"trick","src":"stop:factor-count-stones#idea","title":"Counting factors from the stones","body":"For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts. 2³ × 3² is 72. Every factor of 72 is built only from 72's own stones, and it cannot use more of a stone than 72 has. So a factor takes some of the three 2s — none, one, two or three of them: 4 choices — and some of the two 3s — none, one or two: 3 choices.","cta":"Learn the trick","level":8,"route":"#/stop/factor-count-stones"},"story-factor-count-stones-open":{"id":"story-factor-count-stones-open","kind":"story","src":"story:factor-count-stones#open","badge":{"id":"story","label":"A story"},"title":"Bags of biscuits","body":"The bakery has 72 biscuits to pack into equal bags, none left over. How many different bag sizes could work? — with Suki and Rafi.","art":"art/s-bakery.webp","cta":"Read the story","level":8,"route":"#/stop/factor-count-stones"},"idea-factor-count-stones-case0":{"id":"idea-factor-count-stones-case0","kind":"idea","src":"stop:factor-count-stones#case0","title":"Counting factors from the stones: Every stone has a power","body":"Three 2s give 4 choices (none, one, two, three) and two 3s give 3 choices. Every pairing is a different factor.","cta":"See it worked","level":8,"route":"#/stop/factor-count-stones"},"idea-factor-count-stones-case1":{"id":"idea-factor-count-stones-case1","kind":"idea","src":"stop:factor-count-stones#case1","title":"Counting factors from the stones: A stone on its own","body":"A stone with no little number is there ONCE: a factor can take none of it or one. That is 2 choices, not 1.","cta":"See it worked","level":8,"route":"#/stop/factor-count-stones"},"why-factor-count-stones-why1":{"id":"why-factor-count-stones-why1","kind":"why","src":"stop:factor-count-stones#why1","title":"Why “Counting factors from the stones” works","body":"Every choice of 2s can go with every choice of 3s, and each pairing builds a DIFFERENT factor, because a number has only one set of stones. Picture a table with 4 rows (1, 2, 4, 8) and 3 columns (1, 3, 9): each cell is one factor, and 4 × 3 = 12 cells.","cta":"See why","level":8,"route":"#/stop/factor-count-stones"},"algebra-factor-count-stones-alg":{"id":"algebra-factor-count-stones-alg","kind":"algebra","src":"stop:factor-count-stones#alg","title":"The algebra behind “Counting factors from the stones”","body":"n = p^a × q^b × r^c ⇒ number of factors = (a + 1)(b + 1)(c + 1)","cta":"See why","level":8,"route":"#/stop/factor-count-stones"},"moral-factor-count-stones-beat5":{"id":"moral-factor-count-stones-beat5","kind":"moral","src":"story:factor-count-stones#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Bags of biscuits”","body":"Each pair of choices builds a different size. Twelve bag sizes.","cta":"Read the story","level":8,"route":"#/stop/factor-count-stones"},"try-factor-count-stones-L8":{"id":"try-factor-count-stones-L8","kind":"try","level":8,"src":"try:factor-count-stones@8/1#0","title":"Counting factors from the stones — your turn","route":"#/stop/factor-count-stones","cta":"Practise this stop","play":{"q":"3 × 7³ — how many factors?","opts":["8","2","4"],"after":"For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts."}},"hook-nikhilam-10-hook":{"id":"hook-nikhilam-10-hook","kind":"hook","src":"stop:nikhilam-10#hook","title":"Can you? — Near ten: the cross","body":"8 × 7 — using only how far each is from 10.","cta":"Find out how","level":8,"route":"#/stop/nikhilam-10"},"worked-nikhilam-10-worked0":{"id":"worked-nikhilam-10-worked0","kind":"worked","src":"stop:nikhilam-10#worked0","title":"Worked out — Near ten: the cross: The gaps make the ones","body":"8 × 7: How far is 8 below 10? → 2 · How far is 7 below 10? → 3 · Cross: 8 − 3 (tens) → 5 · Multiply the gaps: 2 × 3 → 6 · 5 tens and 6 → 56","cta":"Watch it step by step","level":8,"route":"#/stop/nikhilam-10"},"worked-nikhilam-10-worked1":{"id":"worked-nikhilam-10-worked1","kind":"worked","src":"stop:nikhilam-10#worked1","title":"Worked out — Near ten: the cross: The gaps make 10 or more","body":"6 × 7: How far is 6 below 10? → 4 · How far is 7 below 10? → 3 · Cross: 6 − 3 (tens) → 3 · Multiply the gaps: 4 × 3 → 12 · 3 tens and 12 → 42","cta":"Watch it step by step","level":8,"route":"#/stop/nikhilam-10"},"why-nikhilam-10-why2":{"id":"why-nikhilam-10-why2","kind":"why","src":"stop:nikhilam-10#why2","title":"Why “Near ten: the cross” works","body":"Why: multiplying (10 − x) by (10 − y) always leaves 10 lots of (10 − x − y), and x × y over. The cross IS 10 − x − y.","cta":"See why","level":8,"route":"#/stop/nikhilam-10"},"sutra-nikhilam-10-sutra":{"id":"sutra-nikhilam-10-sutra","kind":"sutra","src":"stop:nikhilam-10#sutra","title":"Nikhilam Navataścaramaṁ Daśataḥ","body":"“all from nine and the last from ten” — the sutra behind Near ten: the cross.","cta":"Open the stop","level":8,"route":"#/stop/nikhilam-10"},"moral-nikhilam-10-beat5":{"id":"moral-nikhilam-10-beat5","kind":"moral","src":"story:nikhilam-10#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The lantern crates”","body":"Five tens and six… fifty-six lanterns!","cta":"Read the story","level":8,"route":"#/stop/nikhilam-10"},"try-nikhilam-10-L8":{"id":"try-nikhilam-10-L8","kind":"try","level":8,"src":"try:nikhilam-10@8/2#0","title":"Near ten: the cross — your turn","route":"#/stop/nikhilam-10","cta":"Practise this stop","play":{"q":"6 × 5 = ?","opts":["30","4","5"],"after":"Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones."}},"trick-nikhilam-100-idea":{"id":"trick-nikhilam-100-idea","kind":"trick","src":"stop:nikhilam-100#idea","title":"Near a hundred","body":"The same cross, around 100: cross-subtract for the hundreds, multiply the gaps for the last two digits. 97 is 3 below 100, 96 is 4 below. 97 − 4 = 93 hundreds. 3 × 4 = 12, written as two digits. Answer: 9312.","cta":"Learn the trick","level":8,"route":"#/stop/nikhilam-100"},"story-nikhilam-100-open":{"id":"story-nikhilam-100-open","kind":"story","src":"story:nikhilam-100#open","badge":{"id":"story","label":"A story"},"title":"The stadium race","body":"The stadium has 97 rows, with 96 seats in every row. Kwame and Vesper race to count them. — with Kwame and Vesper.","art":"art/s-stadium.webp","cta":"Read the story","level":8,"route":"#/stop/nikhilam-100"},"hook-nikhilam-100-hook":{"id":"hook-nikhilam-100-hook","kind":"hook","src":"stop:nikhilam-100#hook","title":"Can you? — Near a hundred","body":"97 × 96 — a four-digit answer, in your head.","cta":"Find out how","level":8,"route":"#/stop/nikhilam-100"},"idea-nikhilam-100-case0":{"id":"idea-nikhilam-100-case0","kind":"idea","src":"stop:nikhilam-100#case0","title":"Near a hundred: The gaps make two digits","body":"The gaps multiply to a two-digit number, which fills the last two places exactly.","cta":"See it worked","level":8,"route":"#/stop/nikhilam-100"},"worked-nikhilam-100-worked0":{"id":"worked-nikhilam-100-worked0","kind":"worked","src":"stop:nikhilam-100#worked0","title":"Worked out — Near a hundred: The gaps make two digits","body":"97 × 96: 97 is how far below 100? → 3 · 96 is how far below 100? → 4 · Cross: 97 − 4 (hundreds) → 93 · Gaps: 3 × 4 (last two digits) → 12 · 93 hundreds and 12 → 9312","cta":"Watch it step by step","level":8,"route":"#/stop/nikhilam-100"},"idea-nikhilam-100-case1":{"id":"idea-nikhilam-100-case1","kind":"idea","src":"stop:nikhilam-100#case1","title":"Near a hundred: The gaps make under 10","body":"The last part still needs two places, so write a 0 in front: 2 × 3 is 06, not 6.","cta":"See it worked","level":8,"route":"#/stop/nikhilam-100"},"worked-nikhilam-100-worked1":{"id":"worked-nikhilam-100-worked1","kind":"worked","src":"stop:nikhilam-100#worked1","title":"Worked out — Near a hundred: The gaps make under 10","body":"98 × 97: 98 is how far below 100? → 2 · 97 is how far below 100? → 3 · Cross: 98 − 3 (hundreds) → 95 · Gaps: 2 × 3 (last two digits) → 6 · 95 hundreds and 6 → 9506","cta":"Watch it step by step","level":8,"route":"#/stop/nikhilam-100"},"idea-nikhilam-100-case2":{"id":"idea-nikhilam-100-case2","kind":"idea","src":"stop:nikhilam-100#case2","title":"Near a hundred: The gaps make 100 or more","body":"Three digits will not fit in two places. The extra hundred carries across to join the hundreds.","cta":"See it worked","level":8,"route":"#/stop/nikhilam-100"},"worked-nikhilam-100-worked2":{"id":"worked-nikhilam-100-worked2","kind":"worked","src":"stop:nikhilam-100#worked2","title":"Worked out — Near a hundred: The gaps make 100 or more","body":"88 × 87: 88 is how far below 100? → 12 · 87 is how far below 100? → 13 · Cross: 88 − 13 (hundreds) → 75 · Gaps: 12 × 13 (last two digits) → 156 · 75 hundreds and 156 → 7656","cta":"Watch it step by step","level":8,"route":"#/stop/nikhilam-100"},"why-nikhilam-100-why1":{"id":"why-nikhilam-100-why1","kind":"why","src":"stop:nikhilam-100#why1","title":"Why “Near a hundred” works","body":"The last part always gets TWO places, because the base is 100 — so a small one needs a 0 in front: 98 × 97 is 95 hundreds and 06, which is 9506. If the gaps multiply to 100 or more, the extra hundreds carry across: 88 × 87 → 75 hundreds and 12 × 13 = 156, so 7500 + 156 = 7656.","cta":"See why","level":8,"route":"#/stop/nikhilam-100"},"algebra-nikhilam-100-alg":{"id":"algebra-nikhilam-100-alg","kind":"algebra","src":"stop:nikhilam-100#alg","title":"The algebra behind “Near a hundred”","body":"(100 − x)(100 − y) = 100(100 − x − y) + xy","cta":"See why","level":8,"route":"#/stop/nikhilam-100"},"sutra-nikhilam-100-sutra":{"id":"sutra-nikhilam-100-sutra","kind":"sutra","src":"stop:nikhilam-100#sutra","title":"Nikhilam Navataścaramaṁ Daśataḥ","body":"“all from nine and the last from ten” — the sutra behind Near a hundred.","cta":"Open the stop","level":8,"route":"#/stop/nikhilam-100"},"moment-nikhilam-100-beat3":{"id":"moment-nikhilam-100-beat3","kind":"moment","src":"story:nikhilam-100#beat3","badge":{"id":"story","label":"A story"},"title":"The stadium race — on the notepad","body":"Kwame: Cross over: 97 take away 4. That is the hundreds. 97 − 4 = 93","cta":"Read the story","level":8,"route":"#/stop/nikhilam-100"},"moral-nikhilam-100-beat6":{"id":"moral-nikhilam-100-beat6","kind":"moral","src":"story:nikhilam-100#beat6","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The stadium race”","body":"You were ahead of me again.","cta":"Read the story","level":8,"route":"#/stop/nikhilam-100"},"try-nikhilam-100-L8":{"id":"try-nikhilam-100-L8","kind":"try","level":8,"src":"try:nikhilam-100@8/2#0","title":"Near a hundred — your turn","route":"#/stop/nikhilam-100","cta":"Practise this stop","play":{"q":"96 × 92 = ?","opts":["8832","4","8"],"after":"The same cross, around 100: cross-subtract for the hundreds, multiply the gaps for the last two digits."}},"trick-above-100-idea":{"id":"trick-above-100-idea","kind":"trick","src":"stop:above-100#idea","title":"Just above a hundred","body":"Add one number to the other one's surplus; then multiply the surpluses for the last two digits. 104 is 4 over, 107 is 7 over. 104 + 7 = 111 hundreds. 4 × 7 = 28. Answer: 11128.","cta":"Learn the trick","level":8,"route":"#/stop/above-100"},"story-above-100-open":{"id":"story-above-100-open","kind":"story","src":"story:above-100#open","badge":{"id":"story","label":"A story"},"title":"The sticker order","body":"The school orders 104 packs of stickers, with 107 stickers in each pack. — with Theo and Kwame.","art":"art/s-library.webp","cta":"Read the story","level":8,"route":"#/stop/above-100"},"hook-above-100-hook":{"id":"hook-above-100-hook","kind":"hook","src":"stop:above-100#hook","title":"Can you? — Just above a hundred","body":"104 × 107 — above the base works too.","cta":"Find out how","level":8,"route":"#/stop/above-100"},"worked-above-100-worked0":{"id":"worked-above-100-worked0","kind":"worked","src":"stop:above-100#worked0","title":"Worked out — Just above a hundred: Surpluses make two digits","body":"104 × 107: 104 is how far above 100? → 4 · 107 is how far above 100? → 7 · Cross: 104 + 7 (hundreds) → 111 · Surpluses: 4 × 7 → 28 · 111 hundreds and 28 → 11128","cta":"Watch it step by step","level":8,"route":"#/stop/above-100"},"worked-above-100-worked1":{"id":"worked-above-100-worked1","kind":"worked","src":"stop:above-100#worked1","title":"Worked out — Just above a hundred: Surpluses make under 10","body":"102 × 103: 102 is how far above 100? → 2 · 103 is how far above 100? → 3 · Cross: 102 + 3 (hundreds) → 105 · Surpluses: 2 × 3 → 6 · 105 hundreds and 6 → 10506","cta":"Watch it step by step","level":8,"route":"#/stop/above-100"},"worked-above-100-worked2":{"id":"worked-above-100-worked2","kind":"worked","src":"stop:above-100#worked2","title":"Worked out — Just above a hundred: Surpluses make 100 or more","body":"112 × 115: 112 is how far above 100? → 12 · 115 is how far above 100? → 15 · Cross: 112 + 15 (hundreds) → 127 · Surpluses: 12 × 15 → 180 · 127 hundreds and 180 → 12880","cta":"Watch it step by step","level":8,"route":"#/stop/above-100"},"why-above-100-why1":{"id":"why-above-100-why1","kind":"why","src":"stop:above-100#why1","title":"Why “Just above a hundred” works","body":"Below the base you subtract across; above it you add. It is the same algebra with the signs turned over.","cta":"See why","level":8,"route":"#/stop/above-100"},"why-above-100-why2":{"id":"why-above-100-why2","kind":"why","src":"stop:above-100#why2","title":"Why “Just above a hundred” works","body":"The last part still gets two places: 102 × 103 is 105 hundreds and 06, so 10506. And if the surpluses multiply to 100 or more, the extra hundreds carry: 112 × 115 is 127 hundreds and 180, so 12880.","cta":"See why","level":8,"route":"#/stop/above-100"},"sutra-above-100-sutra":{"id":"sutra-above-100-sutra","kind":"sutra","src":"stop:above-100#sutra","title":"Nikhilam","body":"“the same method, above the base” — the sutra behind Just above a hundred.","cta":"Open the stop","level":8,"route":"#/stop/above-100"},"moment-above-100-beat3":{"id":"moment-above-100-beat3","kind":"moment","src":"story:above-100#beat3","badge":{"id":"story","label":"A story"},"title":"The sticker order — on the notepad","body":"Kwame: 104 plus the other one’s 7 — that is the hundreds. 104 + 7 = 111","cta":"Read the story","level":8,"route":"#/stop/above-100"},"moral-above-100-beat5":{"id":"moral-above-100-beat5","kind":"moral","src":"story:above-100#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The sticker order”","body":"11,128 stickers.","cta":"Read the story","level":8,"route":"#/stop/above-100"},"try-above-100-L8":{"id":"try-above-100-L8","kind":"try","level":8,"src":"try:above-100@8/2#0","title":"Just above a hundred — your turn","route":"#/stop/above-100","cta":"Practise this stop","play":{"q":"102 × 101 = ?","opts":["10302","2","1"],"after":"Add one number to the other one's surplus; then multiply the surpluses for the last two digits."}},"trick-crosswise-idea":{"id":"trick-crosswise-idea","kind":"trick","src":"stop:crosswise#idea","title":"Vertically and crosswise","body":"Multiply the units (vertically), then cross-multiply and add (crosswise), then the tens (vertically). Carry as you go. 23 × 41: units 3 × 1 = 3. Crosswise 2 × 1 + 3 × 4 = 14 — write 4, carry 1. Tens 2 × 4 = 8, plus the carried 1 = 9. Answer: 943.","cta":"Learn the trick","level":8,"route":"#/stop/crosswise"},"story-crosswise-open":{"id":"story-crosswise-open","kind":"story","src":"story:crosswise#open","badge":{"id":"story","label":"A story"},"title":"One line","body":"Contest practice. The question is 23 × 41. Vesper writes a single line. — with Vesper and Mira.","art":"art/s-night.webp","cta":"Read the story","level":8,"route":"#/stop/crosswise"},"hook-crosswise-hook":{"id":"hook-crosswise-hook","kind":"hook","src":"stop:crosswise#hook","title":"Can you? — Vertically and crosswise","body":"23 × 41 — any two-digit numbers, one line.","cta":"Find out how","level":8,"route":"#/stop/crosswise"},"idea-crosswise-case0":{"id":"idea-crosswise-case0","kind":"idea","src":"stop:crosswise#case0","title":"Vertically and crosswise: No carrying","body":"Every step gives a single digit, so the three answers are simply the three digits, read tens-first.","cta":"See it worked","level":8,"route":"#/stop/crosswise"},"worked-crosswise-worked0":{"id":"worked-crosswise-worked0","kind":"worked","src":"stop:crosswise#worked0","title":"Worked out — Vertically and crosswise: No carrying","body":"21 × 32: Units: 1 × 2 → 2 · Crosswise: 2 × 2 + 1 × 3 → 7 · Tens: 2 × 3 → 6 · Carry and read → 672","cta":"Watch it step by step","level":8,"route":"#/stop/crosswise"},"idea-crosswise-case1":{"id":"idea-crosswise-case1","kind":"idea","src":"stop:crosswise#case1","title":"Vertically and crosswise: The crosswise carries","body":"The crosswise step makes 10 or more. Keep its ones digit and carry the ten into the next step.","cta":"See it worked","level":8,"route":"#/stop/crosswise"},"worked-crosswise-worked1":{"id":"worked-crosswise-worked1","kind":"worked","src":"stop:crosswise#worked1","title":"Worked out — Vertically and crosswise: The crosswise carries","body":"23 × 41: Units: 3 × 1 → 3 · Crosswise: 2 × 1 + 3 × 4 → 14 · Tens: 2 × 4 → 8 · Carry and read → 943","cta":"Watch it step by step","level":8,"route":"#/stop/crosswise"},"idea-crosswise-case2":{"id":"idea-crosswise-case2","kind":"idea","src":"stop:crosswise#case2","title":"Vertically and crosswise: The units carry","body":"Now the very first step makes 10 or more. Its tens join the crosswise sum before you write anything.","cta":"See it worked","level":8,"route":"#/stop/crosswise"},"worked-crosswise-worked2":{"id":"worked-crosswise-worked2","kind":"worked","src":"stop:crosswise#worked2","title":"Worked out — Vertically and crosswise: The units carry","body":"27 × 34: Units: 7 × 4 → 28 · Crosswise: 2 × 4 + 7 × 3 → 29 · Tens: 2 × 3 → 6 · Carry and read → 918","cta":"Watch it step by step","level":8,"route":"#/stop/crosswise"},"why-crosswise-why1":{"id":"why-crosswise-why1","kind":"why","src":"stop:crosswise#why1","title":"Why “Vertically and crosswise” works","body":"It is the long-multiplication grid with all four boxes added in your head, column by column, right to left. The crosswise step is the two boxes that both land in the tens column.","cta":"See why","level":8,"route":"#/stop/crosswise"},"why-crosswise-why2":{"id":"why-crosswise-why2","kind":"why","src":"stop:crosswise#why2","title":"Why “Vertically and crosswise” works","body":"The units can carry too. 27 × 34: units 7 × 4 = 28 — write 8, carry 2. Crosswise 2 × 4 + 7 × 3 = 29, plus the 2 is 31 — write 1, carry 3. Tens 2 × 3 = 6, plus 3 is 9. Answer: 918.","cta":"See why","level":8,"route":"#/stop/crosswise"},"algebra-crosswise-alg":{"id":"algebra-crosswise-alg","kind":"algebra","src":"stop:crosswise#alg","title":"The algebra behind “Vertically and crosswise”","body":"(10a + b)(10c + d) = 100ac + 10(ad + bc) + bd","cta":"See why","level":8,"route":"#/stop/crosswise"},"sutra-crosswise-sutra":{"id":"sutra-crosswise-sutra","kind":"sutra","src":"stop:crosswise#sutra","title":"Ūrdhva-tiryagbhyām","body":"“vertically and crosswise” — the sutra behind Vertically and crosswise.","cta":"Open the stop","level":8,"route":"#/stop/crosswise"},"moment-crosswise-beat2":{"id":"moment-crosswise-beat2","kind":"moment","src":"story:crosswise#beat2","badge":{"id":"story","label":"A story"},"title":"One line — on the notepad","body":"Vesper: Crosswise: 2 times 1, plus 3 times 4. 2 × 1 + 3 × 4 = 14","cta":"Read the story","level":8,"route":"#/stop/crosswise"},"moral-crosswise-beat5":{"id":"moral-crosswise-beat5","kind":"moral","src":"story:crosswise#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “One line”","body":"It is only the long-multiplication grid, done in your head.","cta":"Read the story","level":8,"route":"#/stop/crosswise"},"try-crosswise-L8":{"id":"try-crosswise-L8","kind":"try","level":8,"src":"try:crosswise@8/1#0","title":"Vertically and crosswise — your turn","route":"#/stop/crosswise","cta":"Practise this stop","play":{"q":"31 × 21 = ?","opts":["651","1","5"],"after":"Multiply the units (vertically), then cross-multiply and add (crosswise), then the tens (vertically). Carry as you go."}},"trick-odd-staircase-idea":{"id":"trick-odd-staircase-idea","kind":"trick","src":"stop:odd-staircase#idea","title":"The odd-number staircase","body":"Add the odd numbers from 1, and you always land on a square: count how many you added, and square that. Start with one dot. Wrap 3 dots round its corner and you have a 2-by-2 square. Wrap 5 round that and you have 3 by 3. Each new odd number is exactly the \"L\" that turns one square into the next one up.","cta":"Learn the trick","level":8,"route":"#/stop/odd-staircase"},"story-odd-staircase-open":{"id":"story-odd-staircase-open","kind":"story","src":"story:odd-staircase#open","badge":{"id":"story","label":"A story"},"title":"The garden tiles","body":"In the palace garden, Nova lays tiles: 1 gold tile, then 3 around its corner, then 5, then 7, then 9. — with Mira and Nova.","art":"art/s-garden.webp","cta":"Read the story","level":8,"route":"#/stop/odd-staircase"},"hook-odd-staircase-hook":{"id":"hook-odd-staircase-hook","kind":"hook","src":"stop:odd-staircase#hook","title":"Can you? — The odd-number staircase","body":"1 + 3 + 5 + 7 + 9 — add them, and look what you get.","cta":"Find out how","level":8,"route":"#/stop/odd-staircase"},"idea-odd-staircase-case0":{"id":"idea-odd-staircase-case0","kind":"idea","src":"stop:odd-staircase#case0","title":"The odd-number staircase: Add the odd numbers","body":"Count how many odd numbers you are adding, and square that count — each one is the L that grows the square.","cta":"See it worked","level":8,"route":"#/stop/odd-staircase"},"worked-odd-staircase-worked0":{"id":"worked-odd-staircase-worked0","kind":"worked","src":"stop:odd-staircase#worked0","title":"Worked out — The odd-number staircase: Add the odd numbers","body":"1 + 3 + 5 + 7 + 9: How many odd numbers? (9 + 1) ÷ 2 → 5 · 5² → 25","cta":"Watch it step by step","level":8,"route":"#/stop/odd-staircase"},"idea-odd-staircase-case1":{"id":"idea-odd-staircase-case1","kind":"idea","src":"stop:odd-staircase#case1","title":"The odd-number staircase: A long list","body":"You only see the last odd number. Add 1 and halve it to find how many there are, then square.","cta":"See it worked","level":8,"route":"#/stop/odd-staircase"},"worked-odd-staircase-worked1":{"id":"worked-odd-staircase-worked1","kind":"worked","src":"stop:odd-staircase#worked1","title":"Worked out — The odd-number staircase: A long list","body":"1 + 3 + 5 + … + 15: How many odd numbers? (15 + 1) ÷ 2 → 8 · 8² → 64","cta":"Watch it step by step","level":8,"route":"#/stop/odd-staircase"},"idea-odd-staircase-case2":{"id":"idea-odd-staircase-case2","kind":"idea","src":"stop:odd-staircase#case2","title":"The odd-number staircase: The gap to the next square","body":"Now run it backwards: the L that turns one square into the next is a row, a column and one corner.","cta":"See it worked","level":8,"route":"#/stop/odd-staircase"},"worked-odd-staircase-worked2":{"id":"worked-odd-staircase-worked2","kind":"worked","src":"stop:odd-staircase#worked2","title":"Worked out — The odd-number staircase: The gap to the next square","body":"10² + ? = 11²: A row of 10 and a column of 10 → 20 · And one for the corner → 21","cta":"Watch it step by step","level":8,"route":"#/stop/odd-staircase"},"why-odd-staircase-why1":{"id":"why-odd-staircase-why1","kind":"why","src":"stop:odd-staircase#why1","title":"Why “The odd-number staircase” works","body":"Why odd? To grow an n-by-n square to (n + 1) by (n + 1) you add a row of n, a column of n, and one dot in the corner: n + n + 1, which is always odd. So the first five odd numbers make 5 × 5 = 25. When the list is too long to write out, find how many odd numbers there are from the last one: add 1 and halve. 1 + 3 + … + 15 has (15 + 1) ÷ 2 = 8 of them, so it makes 8² = 64.","cta":"See why","level":8,"route":"#/stop/odd-staircase"},"why-odd-staircase-why2":{"id":"why-odd-staircase-why2","kind":"why","src":"stop:odd-staircase#why2","title":"Why “The odd-number staircase” works","body":"It works the other way too: the gap between two squares next to each other is an odd number — 15² + 31 = 16². That is the same \"next square up\" idea you may meet in the Harbour.","cta":"See why","level":8,"route":"#/stop/odd-staircase"},"algebra-odd-staircase-alg":{"id":"algebra-odd-staircase-alg","kind":"algebra","src":"stop:odd-staircase#alg","title":"The algebra behind “The odd-number staircase”","body":"1 + 3 + 5 + … + (2n − 1) = n²","cta":"See why","level":8,"route":"#/stop/odd-staircase"},"moment-odd-staircase-beat4":{"id":"moment-odd-staircase-beat4","kind":"moment","src":"story:odd-staircase#beat4","badge":{"id":"story","label":"A story"},"title":"The garden tiles — on the notepad","body":"Mira: Five odd numbers make five squared. No adding needed. 5 × 5 = 25","cta":"Read the story","level":8,"route":"#/stop/odd-staircase"},"moral-odd-staircase-beat5":{"id":"moral-odd-staircase-beat5","kind":"moral","src":"story:odd-staircase#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “The garden tiles”","body":"Twenty-five tiles. The odd numbers were climbing a staircase of squares.","cta":"Read the story","level":8,"route":"#/stop/odd-staircase"},"try-odd-staircase-L8":{"id":"try-odd-staircase-L8","kind":"try","level":8,"src":"try:odd-staircase@8/2#0","title":"The odd-number staircase — your turn","route":"#/stop/odd-staircase","cta":"Practise this stop","play":{"q":"1 + 3 + 5 + … + 13 = ?","opts":["49","7","50"],"after":"Add the odd numbers from 1, and you always land on a square: count how many you added, and square that."}},"trick-square-near-50-idea":{"id":"trick-square-near-50-idea","kind":"trick","src":"stop:square-near-50#idea","title":"Squares near fifty","body":"Start at 2500. Each step away from 50 adds (or takes) 100; then add the gap squared. 47 is 50 − 3. By the strips picture, 47² = 50² − 2 × 50 × 3 + 3² = 2500 − 300 + 9 = 2209. The strips are 50 long, so two of them are always 100 × the gap. That is what makes 50 so friendly.","cta":"Learn the trick","level":8,"route":"#/stop/square-near-50"},"story-square-near-50-open":{"id":"story-square-near-50-open","kind":"story","src":"story:square-near-50#open","badge":{"id":"story","label":"A story"},"title":"The rooftop garden","body":"A square rooftop garden is 47 metres on each side. Theo needs its area for the seed order. — with Kwame and Theo.","art":"art/s-city.webp","cta":"Read the story","level":8,"route":"#/stop/square-near-50"},"hook-square-near-50-hook":{"id":"hook-square-near-50-hook","kind":"hook","src":"stop:square-near-50#hook","title":"Can you? — Squares near fifty","body":"47² — using only 50² = 2500.","cta":"Find out how","level":8,"route":"#/stop/square-near-50"},"idea-square-near-50-case0":{"id":"idea-square-near-50-case0","kind":"idea","src":"stop:square-near-50#case0","title":"Squares near fifty: Just below 50","body":"Below 50 the two strips are cut off, so take 100 × the gap away from 2500 — then put the corner back.","cta":"See it worked","level":8,"route":"#/stop/square-near-50"},"worked-square-near-50-worked0":{"id":"worked-square-near-50-worked0","kind":"worked","src":"stop:square-near-50#worked0","title":"Worked out — Squares near fifty: Just below 50","body":"47²: How far from 50? (below) → 3 · The two strips: 100 × 3 → 300 · The corner: 3² → 9 · 2500 − 300 + 9 → 2209","cta":"Watch it step by step","level":8,"route":"#/stop/square-near-50"},"idea-square-near-50-case1":{"id":"idea-square-near-50-case1","kind":"idea","src":"stop:square-near-50#case1","title":"Squares near fifty: Just above 50","body":"Above 50 the strips are added on, and so is the corner: 2500 + 100 × the gap + the gap squared.","cta":"See it worked","level":8,"route":"#/stop/square-near-50"},"worked-square-near-50-worked1":{"id":"worked-square-near-50-worked1","kind":"worked","src":"stop:square-near-50#worked1","title":"Worked out — Squares near fifty: Just above 50","body":"53²: How far from 50? (above) → 3 · The two strips: 100 × 3 → 300 · The corner: 3² → 9 · 2500 + 300 + 9 → 2809","cta":"Watch it step by step","level":8,"route":"#/stop/square-near-50"},"why-square-near-50-why1":{"id":"why-square-near-50-why1","kind":"why","src":"stop:square-near-50#why1","title":"Why “Squares near fifty” works","body":"Above 50 the strips are added instead: 53² = 2500 + 300 + 9 = 2809.","cta":"See why","level":8,"route":"#/stop/square-near-50"},"why-square-near-50-why2":{"id":"why-square-near-50-why2","kind":"why","src":"stop:square-near-50#why2","title":"Why “Squares near fifty” works","body":"There is a shortcut hiding in it: 2500 is 25 hundreds, so (50 ± d)² is (25 ± d) hundreds, plus d². 56² is 31 hundreds and 36: 3136.","cta":"See why","level":8,"route":"#/stop/square-near-50"},"algebra-square-near-50-alg":{"id":"algebra-square-near-50-alg","kind":"algebra","src":"stop:square-near-50#alg","title":"The algebra behind “Squares near fifty”","body":"(50 ± d)² = 2500 ± 100d + d²","cta":"See why","level":8,"route":"#/stop/square-near-50"},"moment-square-near-50-beat3":{"id":"moment-square-near-50-beat3","kind":"moment","src":"story:square-near-50#beat3","badge":{"id":"story","label":"A story"},"title":"The rooftop garden — on the notepad","body":"Kwame: Two strips, each 50 by 3, come off. That is 300. 2 × 50 × 3 = 300","cta":"Read the story","level":8,"route":"#/stop/square-near-50"},"moral-square-near-50-beat5":{"id":"moral-square-near-50-beat5","kind":"moral","src":"story:square-near-50#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The rooftop garden”","body":"Two thousand two hundred and nine square metres. Near fifty, every square is quick.","cta":"Read the story","level":8,"route":"#/stop/square-near-50"},"try-square-near-50-L8":{"id":"try-square-near-50-L8","kind":"try","level":8,"src":"try:square-near-50@8/1#0","title":"Squares near fifty — your turn","route":"#/stop/square-near-50","cta":"Practise this stop","play":{"q":"53² = ?","opts":["2809","3","300"],"after":"Start at 2500. Each step away from 50 adds (or takes) 100; then add the gap squared."}},"trick-index-laws-idea":{"id":"trick-index-laws-idea","kind":"trick","src":"stop:index-laws#idea","title":"The index laws","body":"Multiplying powers of the same number adds the indices; dividing subtracts them. 2³ is three 2s multiplied, and 2⁴ is four more. Put them side by side and you have seven 2s multiplied: 2⁷. You never needed to know that 2³ is 8.","cta":"Learn the trick","level":8,"route":"#/stop/index-laws"},"story-index-laws-open":{"id":"story-index-laws-open","kind":"story","src":"story:index-laws#open","badge":{"id":"story","label":"A story"},"title":"Stars over the palace","body":"A clear night on the palace roof. Rafi reads that there are about 3 × 10⁴ stars in one patch of sky, and 2 × 10³ patches like it. — with Vesper and Rafi.","art":"art/s-night.webp","cta":"Read the story","level":8,"route":"#/stop/index-laws"},"idea-index-laws-case0":{"id":"idea-index-laws-case0","kind":"idea","src":"stop:index-laws#case0","title":"The index laws: Multiplying: add","body":"Put the two lots side by side and count all the 2s together — so the indices add.","cta":"See it worked","level":8,"route":"#/stop/index-laws"},"idea-index-laws-case1":{"id":"idea-index-laws-case1","kind":"idea","src":"stop:index-laws#case1","title":"The index laws: Dividing: take away","body":"Each one underneath cancels one on top, so the indices take away.","cta":"See it worked","level":8,"route":"#/stop/index-laws"},"idea-index-laws-case2":{"id":"idea-index-laws-case2","kind":"idea","src":"stop:index-laws#case2","title":"The index laws: Standard form","body":"One digit before the point, and the power of ten is how many places the point has to move — one fewer than the digits.","cta":"See it worked","level":8,"route":"#/stop/index-laws"},"idea-index-laws-case3":{"id":"idea-index-laws-case3","kind":"idea","src":"stop:index-laws#case3","title":"The index laws: Multiplying in standard form","body":"Multiply the front numbers, add the powers of ten.","cta":"See it worked","level":8,"route":"#/stop/index-laws"},"idea-index-laws-case4":{"id":"idea-index-laws-case4","kind":"idea","src":"stop:index-laws#case4","title":"The index laws: When the front goes past 10","body":"If the front numbers make 10 or more, one ten slides into the power, so the index goes up by one more.","cta":"See it worked","level":8,"route":"#/stop/index-laws"},"why-index-laws-why1":{"id":"why-index-laws-why1","kind":"why","src":"stop:index-laws#why1","title":"Why “The index laws” works","body":"Dividing cancels: 5⁶ ÷ 5² is six 5s on top and two underneath. Each 5 underneath cancels one on top, leaving four: 5⁴. So you take the indices away.","cta":"See why","level":8,"route":"#/stop/index-laws"},"algebra-index-laws-alg":{"id":"algebra-index-laws-alg","kind":"algebra","src":"stop:index-laws#alg","title":"The algebra behind “The index laws”","body":"aᵐ × aⁿ = aᵐ⁺ⁿ   ·   aᵐ ÷ aⁿ = aᵐ⁻ⁿ   ·   standard form: A × 10ⁿ, 1 ≤ A < 10","cta":"See why","level":8,"route":"#/stop/index-laws"},"moral-index-laws-beat5":{"id":"moral-index-laws-beat5","kind":"moral","src":"story:index-laws#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Stars over the palace”","body":"Sixty million stars — and I never wrote a single long row of zeros.","cta":"Read the story","level":8,"route":"#/stop/index-laws"},"try-index-laws-L8":{"id":"try-index-laws-L8","kind":"try","level":8,"src":"try:index-laws@8/1#0","title":"The index laws — your turn","route":"#/stop/index-laws","cta":"Practise this stop","play":{"q":"10⁶ × 10² as one power of 10 — the index?","opts":["8","6","2"],"after":"Multiplying powers of the same number adds the indices; dividing subtracts them."}},"trick-set-member-idea":{"id":"trick-set-member-idea","kind":"trick","src":"stop:set-member#idea","title":"In the set, or not?","body":"A set is decided by its rule. Test the number against the rule: if it passes, it belongs (∈). A set is a collection with a clear rule, so that for any thing at all you can say \"in\" or \"not in\". {multiples of 7} is a set; {big numbers} is not, because nobody can agree where \"big\" starts.","cta":"Learn the trick","level":8,"route":"#/stop/set-member"},"story-set-member-open":{"id":"story-set-member-open","kind":"story","src":"story:set-member#open","badge":{"id":"story","label":"A story"},"title":"The seven-step bridge","body":"On the beach at Set Island, a sign by the rock pools says: only numbers in M = {multiples of 7} may cross. Pip is holding 91. — with Theo and Pip.","art":"art/s-beach.webp","cta":"Read the story","level":8,"route":"#/stop/set-member"},"hook-set-member-hook":{"id":"hook-set-member-hook","kind":"hook","src":"stop:set-member#hook","title":"Can you? — In the set, or not?","body":"M = {multiples of 7}. Is 91 in M?","cta":"Find out how","level":8,"route":"#/stop/set-member"},"idea-set-member-case0":{"id":"idea-set-member-case0","kind":"idea","src":"stop:set-member#case0","title":"In the set, or not?: Multiples","body":"Divide by the number in the rule. Nothing left over means it is a member; any remainder at all means it is not.","cta":"See it worked","level":8,"route":"#/stop/set-member"},"worked-set-member-worked0":{"id":"worked-set-member-worked0","kind":"worked","src":"stop:set-member#worked0","title":"Worked out — In the set, or not?: Multiples","body":"M = {multiples of 7}. Is 91 ∈ M?: Remainder when 91 ÷ 7 → 0 · No remainder means it passes the rule → Yes","cta":"Watch it step by step","level":8,"route":"#/stop/set-member"},"idea-set-member-case1":{"id":"idea-set-member-case1","kind":"idea","src":"stop:set-member#case1","title":"In the set, or not?: Square numbers","body":"Find the whole number whose square is just under or on it. If that square lands exactly on the number, it is in.","cta":"See it worked","level":8,"route":"#/stop/set-member"},"worked-set-member-worked1":{"id":"worked-set-member-worked1","kind":"worked","src":"stop:set-member#worked1","title":"Worked out — In the set, or not?: Square numbers","body":"S = {square numbers}. Is 50 ∈ S?: The biggest whole number whose square is not over 50 → 7 · 7² → 49 · Is that exactly 50? → No","cta":"Watch it step by step","level":8,"route":"#/stop/set-member"},"idea-set-member-case2":{"id":"idea-set-member-case2","kind":"idea","src":"stop:set-member#case2","title":"In the set, or not?: Factors","body":"The rule is turned round: now the number must go INTO the big one. 36 ÷ 8 leaves 4 over, so 8 is not a factor.","cta":"See it worked","level":8,"route":"#/stop/set-member"},"worked-set-member-worked2":{"id":"worked-set-member-worked2","kind":"worked","src":"stop:set-member#worked2","title":"Worked out — In the set, or not?: Factors","body":"F = {factors of 36}. Is 8 ∈ F?: Remainder when 36 ÷ 8 → 4 · No remainder means it is a factor → No","cta":"Watch it step by step","level":8,"route":"#/stop/set-member"},"why-set-member-why1":{"id":"why-set-member-why1","kind":"why","src":"stop:set-member#why1","title":"Why “In the set, or not?” works","body":"We write 91 ∈ M for \"91 is a member of M\" and 90 ∉ M for \"90 is not\". You do not need to list the whole set — it may go on for ever — you only need to test the one number against the rule: 91 ÷ 7 = 13 with nothing left over, so 91 ∈ M.","cta":"See why","level":8,"route":"#/stop/set-member"},"why-set-member-why2":{"id":"why-set-member-why2","kind":"why","src":"stop:set-member#why2","title":"Why “In the set, or not?” works","body":"That is the power of a rule: one quick test answers the question for a set with infinitely many members.","cta":"See why","level":8,"route":"#/stop/set-member"},"algebra-set-member-alg":{"id":"algebra-set-member-alg","kind":"algebra","src":"stop:set-member#alg","title":"The algebra behind “In the set, or not?”","body":"x ∈ A means x is a member of A;  x ∉ A means it is not","cta":"See why","level":8,"route":"#/stop/set-member"},"moment-set-member-beat4":{"id":"moment-set-member-beat4","kind":"moment","src":"story:set-member#beat4","badge":{"id":"story","label":"A story"},"title":"The seven-step bridge — on the notepad","body":"Theo: Thirteen exactly. Check it back the other way. 13 × 7 = 91","cta":"Read the story","level":8,"route":"#/stop/set-member"},"moral-set-member-beat5":{"id":"moral-set-member-beat5","kind":"moral","src":"story:set-member#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The seven-step bridge”","body":"So 91 is a member of M. I can cross! A rule answers it in one sum.","cta":"Read the story","level":8,"route":"#/stop/set-member"},"try-set-member-L8":{"id":"try-set-member-L8","kind":"try","level":8,"src":"try:set-member@8/1#0","title":"In the set, or not? — your turn","route":"#/stop/set-member","cta":"Practise this stop","play":{"q":"M = {multiples of 5}. Is 25 ∈ M?","opts":["Yes","No"],"after":"A set is decided by its rule. Test the number against the rule: if it passes, it belongs (∈)."}},"trick-set-count-idea":{"id":"trick-set-count-idea","kind":"trick","src":"stop:set-count#idea","title":"Counting a set — and the empty set","body":"n(A) is how many members A has. Count by a rule, not one by one — and a set with no members is still a set: the empty set, with n = 0. Listing works for small sets: {red, amber, green} has 3 members, so n(A) = 3. Each member counts once — writing red twice does not make a fourth.","cta":"Learn the trick","level":8,"route":"#/stop/set-count"},"story-set-count-open":{"id":"story-set-count-open","kind":"story","src":"story:set-count#open","badge":{"id":"story","label":"A story"},"title":"Shells in a row","body":"Rafi and Nova number 100 shells along the sand. Every 6th shell is a spotted one. How many spotted shells? — with Rafi and Nova.","art":"art/s-beach.webp","cta":"Read the story","level":8,"route":"#/stop/set-count"},"hook-set-count-hook":{"id":"hook-set-count-hook","kind":"hook","src":"stop:set-count#hook","title":"Can you? — Counting a set — and the empty set","body":"A = {multiples of 6 up to 100}. How many members — without writing them all?","cta":"Find out how","level":8,"route":"#/stop/set-count"},"idea-set-count-case0":{"id":"idea-set-count-case0","kind":"idea","src":"stop:set-count#case0","title":"Counting a set — and the empty set: A run of numbers","body":"Take the first from the last, then add one — the first number is in the set too, like the first post of a fence.","cta":"See it worked","level":8,"route":"#/stop/set-count"},"worked-set-count-worked0":{"id":"worked-set-count-worked0","kind":"worked","src":"stop:set-count#worked0","title":"Worked out — Counting a set — and the empty set: A run of numbers","body":"A = {whole numbers from 12 to 30}. n(A)?: 30 − 12 → 18 · Add one for the first number → 19","cta":"Watch it step by step","level":8,"route":"#/stop/set-count"},"idea-set-count-case1":{"id":"idea-set-count-case1","kind":"idea","src":"stop:set-count#case1","title":"Counting a set — and the empty set: Multiples up to a limit","body":"Find the last multiple that fits under the limit. Its place in the times table is how many there are.","cta":"See it worked","level":8,"route":"#/stop/set-count"},"worked-set-count-worked1":{"id":"worked-set-count-worked1","kind":"worked","src":"stop:set-count#worked1","title":"Worked out — Counting a set — and the empty set: Multiples up to a limit","body":"A = {multiples of 6 up to 100}. n(A)?: The last multiple of 6 not over 100 → 96 · 96 ÷ 6 → 16","cta":"Watch it step by step","level":8,"route":"#/stop/set-count"},"idea-set-count-case2":{"id":"idea-set-count-case2","kind":"idea","src":"stop:set-count#case2","title":"Counting a set — and the empty set: Multiples between two","body":"Count the multiples up to the top, then take away the ones that come before the bottom.","cta":"See it worked","level":8,"route":"#/stop/set-count"},"worked-set-count-worked2":{"id":"worked-set-count-worked2","kind":"worked","src":"stop:set-count#worked2","title":"Worked out — Counting a set — and the empty set: Multiples between two","body":"A = {multiples of 5 from 23 to 61}. n(A)?: Multiples of 5 up to 61 → 12 · Multiples of 5 below 23 → 4 · 12 − 4 → 8","cta":"Watch it step by step","level":8,"route":"#/stop/set-count"},"idea-set-count-case3":{"id":"idea-set-count-case3","kind":"idea","src":"stop:set-count#case3","title":"Counting a set — and the empty set: The empty set","body":"Sometimes the rule lets nothing in at all. That is still a set — the empty set, ∅ — and its count is 0.","cta":"See it worked","level":8,"route":"#/stop/set-count"},"worked-set-count-worked3":{"id":"worked-set-count-worked3","kind":"worked","src":"stop:set-count#worked3","title":"Worked out — Counting a set — and the empty set: The empty set","body":"A = {multiples of 10 from 41 to 48}. n(A)?: Multiples of 10 up to 48 → 4 · Multiples of 10 below 41 → 4 · 4 − 4 — the empty set → 0","cta":"Watch it step by step","level":8,"route":"#/stop/set-count"},"why-set-count-why1":{"id":"why-set-count-why1","kind":"why","src":"stop:set-count#why1","title":"Why “Counting a set — and the empty set” works","body":"For a bigger set, count with arithmetic. The multiples of 6 up to 100 are 6 × 1, 6 × 2, … 6 × 16 = 96 (6 × 17 = 102 is too far). They are numbered 1 to 16, so there are 16. The whole numbers from 12 to 30 are 30 − 12 + 1 = 19: take away, then add one for the fence post at the start.","cta":"See why","level":8,"route":"#/stop/set-count"},"why-set-count-why2":{"id":"why-set-count-why2","kind":"why","src":"stop:set-count#why2","title":"Why “Counting a set — and the empty set” works","body":"Sometimes the rule lets nothing in: {multiples of 10 between 41 and 49}. That is the empty set, written { } or ∅, and n(∅) = 0. It sounds like nothing — but it is the honest answer to \"which ones?\", and every set has it inside.","cta":"See why","level":8,"route":"#/stop/set-count"},"algebra-set-count-alg":{"id":"algebra-set-count-alg","kind":"algebra","src":"stop:set-count#alg","title":"The algebra behind “Counting a set — and the empty set”","body":"n({k, 2k, …} up to N) = ⌊N ÷ k⌋   ·   n({a, …, b}) = b − a + 1   ·   n(∅) = 0","cta":"See why","level":8,"route":"#/stop/set-count"},"moment-set-count-beat4":{"id":"moment-set-count-beat4","kind":"moment","src":"story:set-count#beat4","badge":{"id":"story","label":"A story"},"title":"Shells in a row — on the notepad","body":"Rafi: And how many spotted shells between 41 and 47? None — that is the empty set. 47 − 41 = 6","cta":"Read the story","level":8,"route":"#/stop/set-count"},"moral-set-count-beat5":{"id":"moral-set-count-beat5","kind":"moral","src":"story:set-count#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Shells in a row”","body":"Sixteen spotted shells, counted without counting.","cta":"Read the story","level":8,"route":"#/stop/set-count"},"try-set-count-L8":{"id":"try-set-count-L8","kind":"try","level":8,"src":"try:set-count@8/1#0","title":"Counting a set — and the empty set — your turn","route":"#/stop/set-count","cta":"Practise this stop","play":{"q":"A = {whole numbers from 8 to 24}. n(A)?","opts":["17","16","18"],"after":"n(A) is how many members A has. Count by a rule, not one by one — and a set with no members is still a set: the empty set, with n = 0."}},"trick-union-meet-idea":{"id":"trick-union-meet-idea","kind":"trick","src":"stop:union-meet#idea","title":"Union and intersection","body":"A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once. The union A ∪ B pours both sets into one bag. But a set never holds the same member twice, so anything in BOTH sets goes in only once. For A = {2, 4, 6, 8, 10} and B = {3, 6, 9}, the 6 is shared: 5 + 3 = 8 names, but only 7 different members.","cta":"Learn the trick","level":8,"route":"#/stop/union-meet"},"story-union-meet-open":{"id":"story-union-meet-open","kind":"story","src":"story:union-meet#open","badge":{"id":"story","label":"A story"},"title":"Two teams, one bus","body":"Team A is shirts 2, 4, 6, 8 and 10. Team B is shirts 3, 6 and 9. Everybody in either team gets on the bus. — with Suki and Dax.","art":"art/s-bus.webp","cta":"Read the story","level":8,"route":"#/stop/union-meet"},"idea-union-meet-case0":{"id":"idea-union-meet-case0","kind":"idea","src":"stop:union-meet#case0","title":"Union and intersection: Union of two lists","body":"Pour both lists into one bag, but a shared member goes in only once: add the two counts, then take the shared ones away.","cta":"See it worked","level":8,"route":"#/stop/union-meet"},"idea-union-meet-case1":{"id":"idea-union-meet-case1","kind":"idea","src":"stop:union-meet#case1","title":"Union and intersection: Intersection of two lists","body":"Keep only what is in BOTH lists — walk along one list and tick each member that the other list has too.","cta":"See it worked","level":8,"route":"#/stop/union-meet"},"idea-union-meet-case2":{"id":"idea-union-meet-case2","kind":"idea","src":"stop:union-meet#case2","title":"Union and intersection: Intersection by rule","body":"A multiple of 4 AND of 6 is a multiple of their lowest common multiple, 12 — so count the multiples of 12.","cta":"See it worked","level":8,"route":"#/stop/union-meet"},"idea-union-meet-case3":{"id":"idea-union-meet-case3","kind":"idea","src":"stop:union-meet#case3","title":"Union and intersection: Union by rule","body":"Count each rule on its own and add — but the common multiples were counted twice, so take them away once.","cta":"See it worked","level":8,"route":"#/stop/union-meet"},"why-union-meet-why1":{"id":"why-union-meet-why1","kind":"why","src":"stop:union-meet#why1","title":"Why “Union and intersection” works","body":"The intersection A ∩ B keeps only what is in both — here just {6}, so n(A ∩ B) = 1. Think of ∪ as a cup that holds everything, and ∩ as a bridge: only what stands on both banks.","cta":"See why","level":8,"route":"#/stop/union-meet"},"algebra-union-meet-alg":{"id":"algebra-union-meet-alg","kind":"algebra","src":"stop:union-meet#alg","title":"The algebra behind “Union and intersection”","body":"n(A ∪ B) = n(A) + n(B) − n(A ∩ B)","cta":"See why","level":8,"route":"#/stop/union-meet"},"moral-union-meet-beat5":{"id":"moral-union-meet-beat5","kind":"moral","src":"story:union-meet#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Two teams, one bus”","body":"Seven seats for A union B. The shared ones go in once.","cta":"Read the story","level":8,"route":"#/stop/union-meet"},"try-union-meet-L8":{"id":"try-union-meet-L8","kind":"try","level":8,"src":"try:union-meet@8/1#0","title":"Union and intersection — your turn","route":"#/stop/union-meet","cta":"Practise this stop","play":{"q":"A = {3, 11, 12}, B = {1, 3, 4, 11}. n(A ∩ B)?","opts":["2","3","1"],"after":"A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once."}},"trick-venn-count-idea":{"id":"trick-venn-count-idea","kind":"trick","src":"stop:venn-count#idea","title":"Venn diagrams that count","body":"Add the two circles, then take away the overlap — it was counted twice. Draw two overlapping circles. The 5 who play both stand in the middle, where the circles cross. Cricket-only is 14 − 5 = 9, chess-only is 11 − 5 = 6. Everybody in a circle: 9 + 5 + 6 = 20.","cta":"Learn the trick","level":8,"route":"#/stop/venn-count"},"story-venn-count-open":{"id":"story-venn-count-open","kind":"story","src":"story:venn-count#open","badge":{"id":"story","label":"A story"},"title":"The club list","body":"In the island hall, 14 children sign up for cricket and 11 for chess. 5 signed up for both. — with Theo and Ines.","art":"art/s-hall.webp","cta":"Read the story","level":8,"route":"#/stop/venn-count"},"idea-venn-count-case0":{"id":"idea-venn-count-case0","kind":"idea","src":"stop:venn-count#case0","title":"Venn diagrams that count: Add the three parts","body":"When the diagram shows every part, each child is in exactly one part — so just add them up.","cta":"See it worked","level":8,"route":"#/stop/venn-count"},"idea-venn-count-case1":{"id":"idea-venn-count-case1","kind":"idea","src":"stop:venn-count#case1","title":"Venn diagrams that count: Add, then take the overlap","body":"The totals for each circle both include the middle, so adding them counts the middle twice. Take it away once.","cta":"See it worked","level":8,"route":"#/stop/venn-count"},"idea-venn-count-case2":{"id":"idea-venn-count-case2","kind":"idea","src":"stop:venn-count#case2","title":"Venn diagrams that count: Find the overlap","body":"Backwards: the class minus \"neither\" is everyone in the circles. Adding the two circles overshoots — by exactly the ones in both.","cta":"See it worked","level":8,"route":"#/stop/venn-count"},"why-venn-count-why1":{"id":"why-venn-count-why1","kind":"why","src":"stop:venn-count#why1","title":"Why “Venn diagrams that count” works","body":"Or quicker: 14 + 11 = 25 counts every child in the middle twice — once as a cricketer, once as a chess player. Take the 5 away once and 20 is left. That rule has a grand name, inclusion–exclusion: include both sets, exclude the overlap.","cta":"See why","level":8,"route":"#/stop/venn-count"},"moral-venn-count-beat5":{"id":"moral-venn-count-beat5","kind":"moral","src":"story:venn-count#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The club list”","body":"Twenty children. Add both circles, take the overlap once.","cta":"Read the story","level":8,"route":"#/stop/venn-count"},"try-venn-count-L8":{"id":"try-venn-count-L8","kind":"try","level":8,"src":"try:venn-count@8/1#0","title":"Venn diagrams that count — your turn","route":"#/stop/venn-count","cta":"Practise this stop","play":{"q":"The Venn diagram shows Piano and Drums. How many are in at least one circle?","opts":["9","5","10"],"after":"Add the two circles, then take away the overlap — it was counted twice."}},"trick-subset-count-idea":{"id":"trick-subset-count-idea","kind":"trick","src":"stop:subset-count#idea","title":"How many subsets?","body":"Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets. A subset is any set made only from members of the big one — including the empty set and the whole set itself. From {a, b} you can make { }, {a}, {b} and {a, b}: four.","cta":"Learn the trick","level":8,"route":"#/stop/subset-count"},"story-subset-count-open":{"id":"story-subset-count-open","kind":"story","src":"story:subset-count#open","badge":{"id":"story","label":"A story"},"title":"Toppings on the pizza","body":"The island café has 4 toppings: olives, peppers, corn and mushroom. Dax wants to try every different pizza. — with Vesper and Dax.","art":"art/s-kitchen.webp","cta":"Read the story","level":8,"route":"#/stop/subset-count"},"idea-subset-count-case0":{"id":"idea-subset-count-case0","kind":"idea","src":"stop:subset-count#case0","title":"How many subsets?: All the subsets","body":"Every member is in or out — two choices each — so double for every member. The empty set and the whole set both count.","cta":"See it worked","level":8,"route":"#/stop/subset-count"},"idea-subset-count-case1":{"id":"idea-subset-count-case1","kind":"idea","src":"stop:subset-count#case1","title":"How many subsets?: Not empty","body":"Only one subset has every member out: the empty set. Count them all, then take away that one.","cta":"See it worked","level":8,"route":"#/stop/subset-count"},"idea-subset-count-case2":{"id":"idea-subset-count-case2","kind":"idea","src":"stop:subset-count#case2","title":"How many subsets?: Must contain a","body":"a has no choice now — it is in. Only the other members get in-or-out, so there are half as many.","cta":"See it worked","level":8,"route":"#/stop/subset-count"},"why-subset-count-why1":{"id":"why-subset-count-why1","kind":"why","src":"stop:subset-count#why1","title":"Why “How many subsets?” works","body":"To build a subset, walk past each member and decide: in, or out? For {a, b, c, d} that is four decisions, each with 2 answers, and every different set of decisions gives a different subset. So there are 2 × 2 × 2 × 2 = 16.","cta":"See why","level":8,"route":"#/stop/subset-count"},"algebra-subset-count-alg":{"id":"algebra-subset-count-alg","kind":"algebra","src":"stop:subset-count#alg","title":"The algebra behind “How many subsets?”","body":"a set with n members has 2ⁿ subsets","cta":"See why","level":8,"route":"#/stop/subset-count"},"moral-subset-count-beat5":{"id":"moral-subset-count-beat5","kind":"moral","src":"story:subset-count#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Toppings on the pizza”","body":"Sixteen pizzas — and one of them is plain, with no topping at all. The empty set counts too!","cta":"Read the story","level":8,"route":"#/stop/subset-count"},"try-subset-count-L8":{"id":"try-subset-count-L8","kind":"try","level":8,"src":"try:subset-count@8/1#0","title":"How many subsets? — your turn","route":"#/stop/subset-count","cta":"Practise this stop","play":{"q":"How many subsets does {a, b} have?","opts":["4","2","5"],"after":"Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets."}},"trick-digit-root-idea":{"id":"trick-digit-root-idea","kind":"trick","src":"stop:digit-root#idea","title":"The nines check","body":"Add a number's digits, and keep adding until one digit is left. Answers keep the same \"digit root\" as the sum that made them. 47 → 4 + 7 = 11 → 2. 23 → 5. 2 × 5 = 10 → 1. And 1081 → 10 → 1. They match, so the answer passes.","cta":"Learn the trick","level":8,"route":"#/stop/digit-root"},"story-digit-root-open":{"id":"story-digit-root-open","kind":"story","src":"story:digit-root#open","badge":{"id":"story","label":"A story"},"title":"Theo checks the till","body":"At the harbour stall, Dax works out 47 × 23 on paper and gets 1081. — with Theo and Dax.","art":"art/s-harbour.webp","cta":"Read the story","level":8,"route":"#/stop/digit-root"},"hook-digit-root-hook":{"id":"hook-digit-root-hook","kind":"hook","src":"stop:digit-root#hook","title":"Can you? — The nines check","body":"You worked out 47 × 23 = 1081. Is it right? Check in five seconds.","cta":"Find out how","level":8,"route":"#/stop/digit-root"},"idea-digit-root-case0":{"id":"idea-digit-root-case0","kind":"idea","src":"stop:digit-root#case0","title":"The nines check: One round of adding","body":"The digits add up to a single digit straight away, so that digit is the root.","cta":"See it worked","level":8,"route":"#/stop/digit-root"},"worked-digit-root-worked0":{"id":"worked-digit-root-worked0","kind":"worked","src":"stop:digit-root#worked0","title":"Worked out — The nines check: One round of adding","body":"Digit root of 312: Add the digits of 312 → 6","cta":"Watch it step by step","level":8,"route":"#/stop/digit-root"},"idea-digit-root-case1":{"id":"idea-digit-root-case1","kind":"idea","src":"stop:digit-root#case1","title":"The nines check: Keep adding","body":"The first sum still has two digits. Do not stop there — add ITS digits, and keep going until one is left.","cta":"See it worked","level":8,"route":"#/stop/digit-root"},"worked-digit-root-worked1":{"id":"worked-digit-root-worked1","kind":"worked","src":"stop:digit-root#worked1","title":"Worked out — The nines check: Keep adding","body":"Digit root of 7384: Add the digits of 7384 → 22 · Add the digits of 22 → 4","cta":"Watch it step by step","level":8,"route":"#/stop/digit-root"},"why-digit-root-why1":{"id":"why-digit-root-why1","kind":"why","src":"stop:digit-root#why1","title":"Why “The nines check” works","body":"This works because 10 is 9 + 1, so every number leaves the same remainder when you divide by 9 as its digits do. Mathematicians have called it \"casting out nines\" for more than a thousand years.","cta":"See why","level":8,"route":"#/stop/digit-root"},"why-digit-root-why2":{"id":"why-digit-root-why2","kind":"why","src":"stop:digit-root#why2","title":"Why “The nines check” works","body":"It catches most slips but not all: it cannot see two digits swapped, because 1081 and 1801 have the same digits. It is a check, not a proof.","cta":"See why","level":8,"route":"#/stop/digit-root"},"algebra-digit-root-alg":{"id":"algebra-digit-root-alg","kind":"algebra","src":"stop:digit-root#alg","title":"The algebra behind “The nines check”","body":"n ≡ (sum of its digits) mod 9","cta":"See why","level":8,"route":"#/stop/digit-root"},"moment-digit-root-beat3":{"id":"moment-digit-root-beat3","kind":"moment","src":"story:digit-root#beat3","badge":{"id":"story","label":"A story"},"title":"Theo checks the till — on the notepad","body":"Theo: Multiply those: 2 times 5, and add the digits again — 1. 2 × 5 = 10","cta":"Read the story","level":8,"route":"#/stop/digit-root"},"moral-digit-root-beat6":{"id":"moral-digit-root-beat6","kind":"moral","src":"story:digit-root#beat6","badge":{"id":"story","label":"A story"},"title":"Theo, in “Theo checks the till”","body":"Almost certainly. The nines check catches most slips — but not two digits swapped.","cta":"Read the story","level":8,"route":"#/stop/digit-root"},"try-digit-root-L8":{"id":"try-digit-root-L8","kind":"try","level":8,"src":"try:digit-root@8/1#0","title":"The nines check — your turn","route":"#/stop/digit-root","cta":"Practise this stop","play":{"q":"Digit root of 53 = ?","opts":["8","9","7"],"after":"Add a number's digits, and keep adding until one digit is left. Answers keep the same \"digit root\" as the sum that made them."}},"trick-divisible-3-idea":{"id":"trick-divisible-3-idea","kind":"trick","src":"stop:divisible-3#idea","title":"Divisible by 3 or 9?","body":"Add up the digits. If the digit sum is in the 3 times table, so is the number. Same for 9. 7 + 8 + 5 + 1 = 21, and 21 is 3 × 7. So 7,851 is divisible by 3. (21 is not in the 9 times table, so 7,851 is not divisible by 9.)","cta":"Learn the trick","level":8,"route":"#/stop/divisible-3"},"story-divisible-3-open":{"id":"story-divisible-3-open","kind":"story","src":"story:divisible-3#open","badge":{"id":"story","label":"A story"},"title":"Three boats","body":"The day’s catch is 7,851 fish, to be shared equally between 3 boats. — with Suki and Rafi.","art":"art/s-harbour.webp","cta":"Read the story","level":8,"route":"#/stop/divisible-3"},"hook-divisible-3-hook":{"id":"hook-divisible-3-hook","kind":"hook","src":"stop:divisible-3#hook","title":"Can you? — Divisible by 3 or 9?","body":"Does 7,851 split into threes? No dividing allowed.","cta":"Find out how","level":8,"route":"#/stop/divisible-3"},"idea-divisible-3-case0":{"id":"idea-divisible-3-case0","kind":"idea","src":"stop:divisible-3#case0","title":"Divisible by 3 or 9?: By 3: yes","body":"The digit sum, 21, is in the 3 times table — so the whole number is too.","cta":"See it worked","level":8,"route":"#/stop/divisible-3"},"worked-divisible-3-worked0":{"id":"worked-divisible-3-worked0","kind":"worked","src":"stop:divisible-3#worked0","title":"Worked out — Divisible by 3 or 9?: By 3: yes","body":"Is 7851 divisible by 3?: Add the digits of 7851 → 21 · Is 21 in the 3 times table? → Yes","cta":"Watch it step by step","level":8,"route":"#/stop/divisible-3"},"idea-divisible-3-case1":{"id":"idea-divisible-3-case1","kind":"idea","src":"stop:divisible-3#case1","title":"Divisible by 3 or 9?: By 3: no","body":"The digit sum, 10, is not in the 3 times table, so the number is not either. No dividing needed to say no.","cta":"See it worked","level":8,"route":"#/stop/divisible-3"},"worked-divisible-3-worked1":{"id":"worked-divisible-3-worked1","kind":"worked","src":"stop:divisible-3#worked1","title":"Worked out — Divisible by 3 or 9?: By 3: no","body":"Is 4321 divisible by 3?: Add the digits of 4321 → 10 · Is 10 in the 3 times table? → No","cta":"Watch it step by step","level":8,"route":"#/stop/divisible-3"},"idea-divisible-3-case2":{"id":"idea-divisible-3-case2","kind":"idea","src":"stop:divisible-3#case2","title":"Divisible by 3 or 9?: By 9: yes","body":"For 9 the digit sum must be in the 9 times table. 18 is, so the number is.","cta":"See it worked","level":8,"route":"#/stop/divisible-3"},"worked-divisible-3-worked2":{"id":"worked-divisible-3-worked2","kind":"worked","src":"stop:divisible-3#worked2","title":"Worked out — Divisible by 3 or 9?: By 9: yes","body":"Is 5832 divisible by 9?: Add the digits of 5832 → 18 · Is 18 in the 9 times table? → Yes","cta":"Watch it step by step","level":8,"route":"#/stop/divisible-3"},"idea-divisible-3-case3":{"id":"idea-divisible-3-case3","kind":"idea","src":"stop:divisible-3#case3","title":"Divisible by 3 or 9?: By 9: no","body":"The same 7,851 as before: 21 is in the 3 times table but not the 9. Divisible by 3 does not mean divisible by 9.","cta":"See it worked","level":8,"route":"#/stop/divisible-3"},"worked-divisible-3-worked3":{"id":"worked-divisible-3-worked3","kind":"worked","src":"stop:divisible-3#worked3","title":"Worked out — Divisible by 3 or 9?: By 9: no","body":"Is 7851 divisible by 9?: Add the digits of 7851 → 21 · Is 21 in the 9 times table? → No","cta":"Watch it step by step","level":8,"route":"#/stop/divisible-3"},"why-divisible-3-why1":{"id":"why-divisible-3-why1","kind":"why","src":"stop:divisible-3#why1","title":"Why “Divisible by 3 or 9?” works","body":"It is the nines check again: a number and its digit sum leave the same remainder when you divide by 9 — and so by 3 as well, because 9 is 3 × 3.","cta":"See why","level":8,"route":"#/stop/divisible-3"},"algebra-divisible-3-alg":{"id":"algebra-divisible-3-alg","kind":"algebra","src":"stop:divisible-3#alg","title":"The algebra behind “Divisible by 3 or 9?”","body":"10ᵏ ≡ 1 (mod 9) ⇒ n ≡ digit sum (mod 9)","cta":"See why","level":8,"route":"#/stop/divisible-3"},"moment-divisible-3-beat3":{"id":"moment-divisible-3-beat3","kind":"moment","src":"story:divisible-3#beat3","badge":{"id":"story","label":"A story"},"title":"Three boats — on the notepad","body":"Suki: 21 is in the three times table. So 7,851 is too. 21 ÷ 3 = 7","cta":"Read the story","level":8,"route":"#/stop/divisible-3"},"moral-divisible-3-beat5":{"id":"moral-divisible-3-beat5","kind":"moral","src":"story:divisible-3#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Three boats”","body":"Not one fish left over.","cta":"Read the story","level":8,"route":"#/stop/divisible-3"},"try-divisible-3-L8":{"id":"try-divisible-3-L8","kind":"try","level":8,"src":"try:divisible-3@8/1#0","title":"Divisible by 3 or 9? — your turn","route":"#/stop/divisible-3","cta":"Practise this stop","play":{"q":"Is 1683 divisible by 3?","opts":["Yes","No"],"after":"Add up the digits. If the digit sum is in the 3 times table, so is the number. Same for 9."}},"trick-diff-squares-idea":{"id":"trick-diff-squares-idea","kind":"trick","src":"stop:diff-squares#idea","title":"Around a middle number","body":"Square the middle number, then take away the square of the distance. 48 and 52 are both 2 away from 50. 50² is 2500. 2² is 4. 2500 − 4 = 2496.","cta":"Learn the trick","level":8,"route":"#/stop/diff-squares"},"story-diff-squares-open":{"id":"story-diff-squares-open","kind":"story","src":"story:diff-squares#open","badge":{"id":"story","label":"A story"},"title":"The dare","body":"Pip dares Vesper: 48 times 52, no paper. — with Vesper and Pip.","art":"art/s-harbour.webp","cta":"Read the story","level":8,"route":"#/stop/diff-squares"},"hook-diff-squares-hook":{"id":"hook-diff-squares-hook","kind":"hook","src":"stop:diff-squares#hook","title":"Can you? — Around a middle number","body":"48 × 52 — two numbers the same distance from 50.","cta":"Find out how","level":8,"route":"#/stop/diff-squares"},"worked-diff-squares-worked0":{"id":"worked-diff-squares-worked0","kind":"worked","src":"stop:diff-squares#worked0","title":"Worked out — Around a middle number","body":"48 × 52: The middle number → 50 · The distance to it → 2 · 50² → 2500 · 2² → 4 · 2500 − 4 → 2496","cta":"Watch it step by step","level":8,"route":"#/stop/diff-squares"},"why-diff-squares-why1":{"id":"why-diff-squares-why1","kind":"why","src":"stop:diff-squares#why1","title":"Why “Around a middle number” works","body":"The picture: a 48-by-52 rectangle is a 50-by-50 square with a strip moved from one side to the other — and a tiny 2-by-2 corner that does not fit. That missing corner is the 4.","cta":"See why","level":8,"route":"#/stop/diff-squares"},"algebra-diff-squares-alg":{"id":"algebra-diff-squares-alg","kind":"algebra","src":"stop:diff-squares#alg","title":"The algebra behind “Around a middle number”","body":"(m − d)(m + d) = m² − d²","cta":"See why","level":8,"route":"#/stop/diff-squares"},"moment-diff-squares-beat2":{"id":"moment-diff-squares-beat2","kind":"moment","src":"story:diff-squares#beat2","badge":{"id":"story","label":"A story"},"title":"The dare — on the notepad","body":"Vesper: Square the distance. 2 × 2 = 4","cta":"Read the story","level":8,"route":"#/stop/diff-squares"},"moral-diff-squares-beat5":{"id":"moral-diff-squares-beat5","kind":"moral","src":"story:diff-squares#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “The dare”","body":"Middle squared, minus distance squared. Every time.","cta":"Read the story","level":8,"route":"#/stop/diff-squares"},"try-diff-squares-L8":{"id":"try-diff-squares-L8","kind":"try","level":8,"src":"try:diff-squares@8/1#0","title":"Around a middle number — your turn","route":"#/stop/diff-squares","cta":"Practise this stop","play":{"q":"29 × 31 = ?","opts":["899","30","1"],"after":"Square the middle number, then take away the square of the distance."}},"trick-pythagoras-side-idea":{"id":"trick-pythagoras-side-idea","kind":"trick","src":"stop:pythagoras-side#idea","title":"Pythagoras’ theorem","body":"In a right-angled triangle, square the two short sides and add: that is the square of the longest side. Draw a square on each side of a right-angled triangle. The big square on the longest side — the hypotenuse, opposite the right angle — has exactly the same area as the two smaller squares put together. With sides 5 and 12, the small squares are 25 and 144, which make 169, and 169 is 13 × 13. So the rope is 13 m.","cta":"Learn the trick","level":8,"route":"#/stop/pythagoras-side"},"story-pythagoras-side-open":{"id":"story-pythagoras-side-open","kind":"story","src":"story:pythagoras-side#open","badge":{"id":"story","label":"A story"},"title":"The mast rope","body":"A boat’s mast stands 12 m tall. A rope runs from the top to a ring on the deck 5 m from the mast’s foot. Mira needs to cut a new rope. — with Mira and Theo.","art":"art/s-harbour.webp","cta":"Read the story","level":8,"route":"#/stop/pythagoras-side"},"idea-pythagoras-side-case0":{"id":"idea-pythagoras-side-case0","kind":"idea","src":"stop:pythagoras-side#case0","title":"Pythagoras’ theorem: Find the longest side","body":"Square the two short sides and ADD: the total is the square on the longest side.","cta":"See it worked","level":8,"route":"#/stop/pythagoras-side"},"idea-pythagoras-side-case1":{"id":"idea-pythagoras-side-case1","kind":"idea","src":"stop:pythagoras-side#case1","title":"Pythagoras’ theorem: Find a short side","body":"Now the longest side is given, so its square is the big one. Take the small square AWAY from it instead of adding.","cta":"See it worked","level":8,"route":"#/stop/pythagoras-side"},"why-pythagoras-side-why1":{"id":"why-pythagoras-side-why1","kind":"why","src":"stop:pythagoras-side#why1","title":"Why “Pythagoras’ theorem” works","body":"Why must it be true? Draw a big square of side a + b and put four copies of the triangle in its corners. Arranged one way, the space left over is one tilted square, c². Arranged another way, it is two squares, a² and b². Same big square, same four triangles, so the space left is the same: a² + b² = c². The theorem carries the name of Pythagoras; a proof of it is Proposition 47 in Book I of Euclid’s Elements.","cta":"See why","level":8,"route":"#/stop/pythagoras-side"},"algebra-pythagoras-side-alg":{"id":"algebra-pythagoras-side-alg","kind":"algebra","src":"stop:pythagoras-side#alg","title":"The algebra behind “Pythagoras’ theorem”","body":"a² + b² = c² , where c is the side opposite the right angle","cta":"See why","level":8,"route":"#/stop/pythagoras-side"},"moral-pythagoras-side-beat6":{"id":"moral-pythagoras-side-beat6","kind":"moral","src":"story:pythagoras-side#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “The mast rope”","body":"Thirteen metres of rope. Measured without leaving the deck.","cta":"Read the story","level":8,"route":"#/stop/pythagoras-side"},"try-pythagoras-side-L8":{"id":"try-pythagoras-side-L8","kind":"try","level":8,"src":"try:pythagoras-side@8/1#0","title":"Pythagoras’ theorem — your turn","route":"#/stop/pythagoras-side","cta":"Practise this stop","play":{"q":"A right-angled triangle has short sides 3 m and 4 m. How long is the longest side?","opts":["5","9","16"],"after":"In a right-angled triangle, square the two short sides and add: that is the square of the longest side."}},"trick-who-has-which-idea":{"id":"trick-who-has-which-idea","kind":"trick","src":"stop:who-has-which#idea","title":"Who won which prize?","body":"Cross out what the clues rule out. When someone has only one prize left, it is theirs — and nobody else can have it. Draw a grid: people down the side, prizes along the top. Every clue puts a cross in a box (\"Asha did not win the kite\") or a tick (\"Ben won the teddy\").","cta":"Learn the trick","level":8,"route":"#/stop/who-has-which"},"story-who-has-which-open":{"id":"story-who-has-which-open","kind":"story","src":"story:who-has-which#open","badge":{"id":"story","label":"A story"},"title":"The prize mix-up","body":"Suki, Theo and Nova each won one prize: a kite, a teddy or a yo-yo. The labels fell off, and there are 2 clues. — with Suki and Theo.","art":"art/s-garden.webp","cta":"Read the story","level":8,"route":"#/stop/who-has-which"},"hook-who-has-which-hook":{"id":"hook-who-has-which-hook","kind":"hook","src":"stop:who-has-which#hook","title":"Can you? — Who won which prize?","body":"Three friends, three prizes, two clues. Can you work out who won what?","cta":"Find out how","level":8,"route":"#/stop/who-has-which"},"idea-who-has-which-case0":{"id":"idea-who-has-which-case0","kind":"idea","src":"stop:who-has-which#case0","title":"Who won which prize?: A tick clue","body":"A tick does double work: Ben has the teddy, so nobody else can — cross out his whole row and the teddy's whole column.","cta":"See it worked","level":8,"route":"#/stop/who-has-which"},"worked-who-has-which-worked0":{"id":"worked-who-has-which-worked0","kind":"worked","src":"stop:who-has-which#worked0","title":"Worked out — Who won which prize?: A tick clue","body":"Asha, Ben and Chen each won one prize: the kite, the teddy or the yo-yo. Asha did not win the kite. Ben won the teddy. Which prize did Asha win?: So which prize must Asha have? → yo-yo","cta":"Watch it step by step","level":8,"route":"#/stop/who-has-which"},"idea-who-has-which-case1":{"id":"idea-who-has-which-case1","kind":"idea","src":"stop:who-has-which#case1","title":"Who won which prize?: Only crosses","body":"No clue says who won what — but a row with one empty box left settles that person, and their prize is crossed out for everyone else.","cta":"See it worked","level":8,"route":"#/stop/who-has-which"},"why-who-has-which-why1":{"id":"why-who-has-which-why1","kind":"why","src":"stop:who-has-which#why1","title":"Why “Who won which prize?” works","body":"A tick does double work. If Ben has the teddy, nobody else can have the teddy, and Ben cannot have anything else — so a tick crosses out its whole row and its whole column.","cta":"See why","level":8,"route":"#/stop/who-has-which"},"why-who-has-which-why2":{"id":"why-who-has-which-why2","kind":"why","src":"stop:who-has-which#why2","title":"Why “Who won which prize?” works","body":"Then look for a row with only one empty box left. That person must have that prize, because everyone wins exactly one. Each answer you find crosses out more boxes, and the rest falls like dominoes.","cta":"See why","level":8,"route":"#/stop/who-has-which"},"algebra-who-has-which-alg":{"id":"algebra-who-has-which-alg","kind":"algebra","src":"stop:who-has-which#alg","title":"The algebra behind “Who won which prize?”","body":"one per row, one per column: a row with one box left is that person's","cta":"See why","level":8,"route":"#/stop/who-has-which"},"moment-who-has-which-beat2":{"id":"moment-who-has-which-beat2","kind":"moment","src":"story:who-has-which#beat2","badge":{"id":"story","label":"A story"},"title":"The prize mix-up — on the notepad","body":"Suki: Draw a grid: 3 people, 3 prizes. 3 × 3 = 9","cta":"Read the story","level":8,"route":"#/stop/who-has-which"},"moral-who-has-which-beat5":{"id":"moral-who-has-which-beat5","kind":"moral","src":"story:who-has-which#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The prize mix-up”","body":"And Nova gets the last one: the kite. Three prizes, three people.","cta":"Read the story","level":8,"route":"#/stop/who-has-which"},"try-who-has-which-L8":{"id":"try-who-has-which-L8","kind":"try","level":8,"src":"try:who-has-which@8/1#0","title":"Who won which prize? — your turn","route":"#/stop/who-has-which","cta":"Practise this stop","play":{"q":"Tara, Lena and Chen each won one prize: the teddy, the yo-yo or the puzzle. Tara won the yo-yo. Chen did not win the puzzle. Which prize did Lena win?","opts":["puzzle","yo-yo","teddy"],"after":"Cross out what the clues rule out. When someone has only one prize left, it is theirs — and nobody else can have it."}},"hook-arrange-all-hook":{"id":"hook-arrange-all-hook","kind":"hook","src":"stop:arrange-all#hook","title":"Can you? — Putting things in order","body":"6 friends queue for the Big Wheel. How many different orders — and what if Pip insists on going first?","cta":"Find out how","level":8,"route":"#/stop/arrange-all"},"worked-arrange-all-worked0":{"id":"worked-arrange-all-worked0","kind":"worked","src":"stop:arrange-all#worked0","title":"Worked out — Putting things in order: Everyone in a row","body":"4 friends queue for the Big Wheel. In how many different orders can they stand?: Choices for the first place → 4 · The other 3 in any order: 3! → 6 · 4 × 6 → 24","cta":"Watch it step by step","level":8,"route":"#/stop/arrange-all"},"worked-arrange-all-worked1":{"id":"worked-arrange-all-worked1","kind":"worked","src":"stop:arrange-all#worked1","title":"Worked out — Putting things in order: One place fixed","body":"5 friends queue for the dodgems, and Pip must be at the front. In how many different orders can they stand?: The first place is decided. How many are left to arrange? → 4 · Arrange them all: 4! = 4 × 3 × 2 × 1 → 24","cta":"Watch it step by step","level":8,"route":"#/stop/arrange-all"},"worked-arrange-all-worked2":{"id":"worked-arrange-all-worked2","kind":"worked","src":"stop:arrange-all#worked2","title":"Worked out — Putting things in order: First from a few","body":"A relay team has 5 runners, and 2 of them are sprinters. A sprinter must run first. In how many different orders can the team run?: How many could run first? → 2 · The other 4 in any order: 4! → 24 · 2 × 24 → 48","cta":"Watch it step by step","level":8,"route":"#/stop/arrange-all"},"why-arrange-all-why2":{"id":"why-arrange-all-why2","kind":"why","src":"stop:arrange-all#why2","title":"Why “Putting things in order” works","body":"If the first place must go to one of a few — say one of 2 sprinters in a team of 5 — the first place has 2 choices, and after it the other 4 can go in any order: 2 × 4! = 48. Always fill the fussy place first.","cta":"See why","level":8,"route":"#/stop/arrange-all"},"moment-arrange-all-beat3":{"id":"moment-arrange-all-beat3","kind":"moment","src":"story:arrange-all#beat3","badge":{"id":"story","label":"A story"},"title":"The dodgem queue — on the notepad","body":"Pip: Three for the second place, two for the third, one for the last. 3 × 2 × 1 = 6","cta":"Read the story","level":8,"route":"#/stop/arrange-all"},"try-arrange-all-L8":{"id":"try-arrange-all-L8","kind":"try","level":8,"src":"try:arrange-all@8/2#0","title":"Putting things in order — your turn","route":"#/stop/arrange-all","cta":"Practise this stop","play":{"q":"7 different prizes go in a row on the shelf, and the teddy must go at the left end. How many different orders?","opts":["720","6","721"],"after":"Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice."}},"trick-permutations-idea":{"id":"trick-permutations-idea","kind":"trick","src":"stop:permutations#idea","title":"Permutations: order matters","body":"When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places. Draw three places: gold, silver, bronze. Any of the 8 runners could win gold. Whoever does, 7 are left for silver, then 6 for bronze. So 8 × 7 × 6 = 336 ways. Stop after 3 places — the other 5 runners get no medal, so their order does not count.","cta":"Learn the trick","level":8,"route":"#/stop/permutations"},"story-permutations-open":{"id":"story-permutations-open","kind":"story","src":"story:permutations#open","badge":{"id":"story","label":"A story"},"title":"The medal table","body":"Eight runners line up for the final at the stadium. There are gold, silver and bronze medals to give out. — with Theo and Kwame.","art":"art/s-stadium.webp","cta":"Read the story","level":8,"route":"#/stop/permutations"},"idea-permutations-case0":{"id":"idea-permutations-case0","kind":"idea","src":"stop:permutations#case0","title":"Permutations: order matters: Order, no repeats","body":"Gold, silver and bronze are different places, and nobody wins two medals: 8, then 7, then 6 choices.","cta":"See it worked","level":8,"route":"#/stop/permutations"},"idea-permutations-case1":{"id":"idea-permutations-case1","kind":"idea","src":"stop:permutations#case1","title":"Permutations: order matters: Repeats allowed","body":"A digit can come back, so every place keeps ALL its choices: 10 × 10 × 10, not 10 × 9 × 8.","cta":"See it worked","level":8,"route":"#/stop/permutations"},"idea-permutations-case2":{"id":"idea-permutations-case2","kind":"idea","src":"stop:permutations#case2","title":"Permutations: order matters: The ⁿPᵣ shorthand","body":"⁷P₃ means \"choose 3 of 7, in order\": start at 7 and multiply 3 numbers going down.","cta":"See it worked","level":8,"route":"#/stop/permutations"},"why-permutations-why1":{"id":"why-permutations-why1","kind":"why","src":"stop:permutations#why1","title":"Why “Permutations: order matters” works","body":"That is 8! with its tail cut off: 8 × 7 × 6 = 8! ÷ 5!. Choosing r things from n in order is written ⁿPᵣ = n! ÷ (n − r)!, and the ÷ (n − r)! simply removes the places nobody fills.","cta":"See why","level":8,"route":"#/stop/permutations"},"algebra-permutations-alg":{"id":"algebra-permutations-alg","kind":"algebra","src":"stop:permutations#alg","title":"The algebra behind “Permutations: order matters”","body":"ⁿPᵣ = n × (n − 1) × … (r factors) = n! ÷ (n − r)! · with repeats: n × n × … = nʳ","cta":"See why","level":8,"route":"#/stop/permutations"},"moral-permutations-beat5":{"id":"moral-permutations-beat5","kind":"moral","src":"story:permutations#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The medal table”","body":"Three hundred and thirty-six ways. Checked.","cta":"Read the story","level":8,"route":"#/stop/permutations"},"try-permutations-L8":{"id":"try-permutations-L8","kind":"try","level":8,"src":"try:permutations@8/1#0","title":"Permutations: order matters — your turn","route":"#/stop/permutations","cta":"Practise this stop","play":{"q":"7 children are in the quiz club. How many ways can a captain and a vice-captain be chosen?","opts":["42","7","6"],"after":"When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places."}},"trick-combinations-idea":{"id":"trick-combinations-idea","kind":"trick","src":"stop:combinations#idea","title":"Combinations: order doesn't matter","body":"Count as if order mattered, then divide by r! — the number of orders each group was counted in. A team of Asha, Ben and Chen is the same team whichever order you pick them in. Count as if order mattered: 7 × 6 × 5 = 210. But every team of 3 has been counted once for each of its orders — ABC, ACB, BAC, BCA, CAB, CBA: 3! = 6 of them. So there are 210 ÷ 6 = 35 teams.","cta":"Learn the trick","level":8,"route":"#/stop/combinations"},"story-combinations-open":{"id":"story-combinations-open","kind":"story","src":"story:combinations#open","badge":{"id":"story","label":"A story"},"title":"Picking the quiz team","body":"Seven children want to be in the quiz final, but a team is only 3. Nova is counting the possible teams. — with Nova and Vesper.","art":"art/s-hall.webp","cta":"Read the story","level":8,"route":"#/stop/combinations"},"idea-combinations-case0":{"id":"idea-combinations-case0","kind":"idea","src":"stop:combinations#case0","title":"Combinations: order doesn't matter: Pairs: halve it","body":"Picking Asha then Ben gives the same pair as Ben then Asha. Count in order, then halve.","cta":"See it worked","level":8,"route":"#/stop/combinations"},"idea-combinations-case1":{"id":"idea-combinations-case1","kind":"idea","src":"stop:combinations#case1","title":"Combinations: order doesn't matter: A group: ÷ r!","body":"Count in order, then divide by the number of orders one team can be picked in: 3! = 6.","cta":"See it worked","level":8,"route":"#/stop/combinations"},"idea-combinations-case2":{"id":"idea-combinations-case2","kind":"idea","src":"stop:combinations#case2","title":"Combinations: order doesn't matter: Choose who stays out","body":"Picking 8 to play is picking 2 to sit out — the same number of ways, and far quicker to count.","cta":"See it worked","level":8,"route":"#/stop/combinations"},"idea-combinations-case3":{"id":"idea-combinations-case3","kind":"idea","src":"stop:combinations#case3","title":"Combinations: order doesn't matter: A chance, by counting","body":"Count the pairs you want, then all the pairs. The chance is one over the other, as a fraction.","cta":"See it worked","level":8,"route":"#/stop/combinations"},"why-combinations-why1":{"id":"why-combinations-why1","kind":"why","src":"stop:combinations#why1","title":"Why “Combinations: order doesn't matter” works","body":"That is ⁿCᵣ = ⁿPᵣ ÷ r! = n! ÷ (r! × (n − r)!). Handshakes are the r = 2 case you have met before: n × (n − 1) counts every pair twice, once from each end, so halve it.","cta":"See why","level":8,"route":"#/stop/combinations"},"algebra-combinations-alg":{"id":"algebra-combinations-alg","kind":"algebra","src":"stop:combinations#alg","title":"The algebra behind “Combinations: order doesn't matter”","body":"ⁿCᵣ = ⁿPᵣ ÷ r! = n! ÷ (r! × (n − r)!) · ⁿCᵣ = ⁿCₙ₋ᵣ","cta":"See why","level":8,"route":"#/stop/combinations"},"moral-combinations-beat5":{"id":"moral-combinations-beat5","kind":"moral","src":"story:combinations#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Picking the quiz team”","body":"Thirty-five teams. Count in order, then divide by the orders.","cta":"Read the story","level":8,"route":"#/stop/combinations"},"try-combinations-L8":{"id":"try-combinations-L8","kind":"try","level":8,"src":"try:combinations@8/1#0","title":"Combinations: order doesn't matter — your turn","route":"#/stop/combinations","cta":"Practise this stop","play":{"q":"The ice-cream stall has 10 flavours. You choose 2 different scoops for a cup. How many different cups?","opts":["45","90","46"],"after":"Count as if order mattered, then divide by r! — the number of orders each group was counted in."}},"word-casting-out-nines":{"id":"word-casting-out-nines","kind":"word","src":"dictionary:casting out nines#def","title":"casting out nines","body":"Checking a calculation by comparing the digit roots of the numbers with the digit root of the answer. For example: 23 × 14 = 322: roots 5 × 5 = 25 → 7, and 3 + 2 + 2 = 7 ✓","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-casting-out-nines":{"id":"wordq-casting-out-nines","kind":"wordq","src":"dictionary:casting out nines#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “23 × 14 = 322: roots 5 × 5 = 25 → 7, and 3 + 2 + 2 = 7 ✓”","opts":["casting out nines","compensation","index laws"],"after":"casting out nines: Checking a calculation by comparing the digit roots of the numbers with the digit root of the answer."},"level":8},"word-difference-of-two-squares":{"id":"word-difference-of-two-squares","kind":"word","src":"dictionary:difference of two squares#def","title":"difference of two squares","body":"One square number taken from another — which always equals (a + b)(a − b). For example: 52² − 48² = 100 × 4 = 400.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-difference-of-two-squares":{"id":"wordq-difference-of-two-squares","kind":"wordq","src":"dictionary:difference of two squares#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “52² − 48² = 100 × 4 = 400.”","opts":["difference of two squares","Vedic maths","acute angle"],"after":"difference of two squares: One square number taken from another — which always equals (a + b)(a − b)."},"level":8},"word-digit-root":{"id":"word-digit-root","kind":"word","src":"dictionary:digit root#def","title":"digit root","body":"Add up the digits of a number, then again, until one digit is left — that last digit is it. For example: 4,787 → 26 → 8.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-digit-root":{"id":"wordq-digit-root","kind":"wordq","src":"dictionary:digit root#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4,787 → 26 → 8.”","opts":["digit root","associative","average"],"after":"digit root: Add up the digits of a number, then again, until one digit is left — that last digit is it."},"level":8},"word-element":{"id":"word-element","kind":"word","src":"dictionary:element#def","title":"element","body":"One of the things inside a set. The sign ∈ means “is in”. For example: 3 ∈ {1, 2, 3}.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-element":{"id":"wordq-element","kind":"wordq","src":"dictionary:element#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 ∈ {1, 2, 3}.”","opts":["element","denominator","metre"],"after":"element: One of the things inside a set. The sign ∈ means “is in”."},"level":8},"word-empty-set":{"id":"word-empty-set","kind":"word","src":"dictionary:empty set#def","title":"empty set","body":"A set with nothing in it, written { } or ∅. For example: Even numbers that are also odd: { }, with 0 things in it.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-empty-set":{"id":"wordq-empty-set","kind":"wordq","src":"dictionary:empty set#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Even numbers that are also odd: { }, with 0 things in it.”","opts":["empty set","rotation","less than"],"after":"empty set: A set with nothing in it, written { } or ∅."},"level":8},"word-nikhilam":{"id":"word-nikhilam","kind":"word","src":"dictionary:nikhilam#def","title":"nikhilam","body":"The method “all from nine and the last from ten”: work with how far numbers are from 10, 100 or 1,000. For example: 1000 − 357: 9 − 3, 9 − 5, 10 − 7 → 643.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-nikhilam":{"id":"wordq-nikhilam","kind":"wordq","src":"dictionary:nikhilam#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “1000 − 357: 9 − 3, 9 − 5, 10 − 7 → 643.”","opts":["nikhilam","negative number","double"],"after":"nikhilam: The method “all from nine and the last from ten”: work with how far numbers are from 10, 100 or 1,000."},"level":8},"word-set":{"id":"word-set","kind":"word","src":"dictionary:set#def","title":"set","body":"A collection of things, each listed once, written inside curly brackets. For example: {2, 4, 6, 8} — the even numbers below 10.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-set":{"id":"wordq-set","kind":"wordq","src":"dictionary:set#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “{2, 4, 6, 8} — the even numbers below 10.”","opts":["set","compound measure","kilometre"],"after":"set: A collection of things, each listed once, written inside curly brackets."},"level":8},"word-sutra":{"id":"word-sutra","kind":"word","src":"dictionary:sutra#def","title":"sutra","body":"A short saying that carries a whole method, like “by one more than the one before”. For example: That one squares 35: 3 × 4 = 12, then 25 → 1,225.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-sutra":{"id":"wordq-sutra","kind":"wordq","src":"dictionary:sutra#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “That one squares 35: 3 × 4 = 12, then 25 → 1,225.”","opts":["sutra","pie chart","formula"],"after":"sutra: A short saying that carries a whole method, like “by one more than the one before”."},"level":8},"word-vedic-maths":{"id":"word-vedic-maths","kind":"word","src":"dictionary:Vedic maths#def","title":"Vedic maths","body":"A set of mental shortcuts with Sanskrit names, set out by Bharati Krishna Tirtha in a book published in 1965. Scholars who have looked have not found them in the Vedas. For example: 98 × 97: 2 short and 3 short of 100 → 95 | 06 = 9,506.","route":"#/lib/dictionary","cta":"Open the Dictionary","source":"Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","level":8},"wordq-vedic-maths":{"id":"wordq-vedic-maths","kind":"wordq","src":"dictionary:Vedic maths#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “98 × 97: 2 short and 3 short of 100 → 95 | 06 = 9,506.”","opts":["Vedic maths","right angle","rhombus"],"after":"Vedic maths: A set of mental shortcuts with Sanskrit names, set out by Bharati Krishna Tirtha in a book published in 1965. Scholars who have looked have not found them in the Vedas."},"level":8},"word-vertically-and-crosswise":{"id":"word-vertically-and-crosswise","kind":"word","src":"dictionary:vertically and crosswise#def","title":"vertically and crosswise","body":"A way to multiply two-digit numbers in one line: the units, then the cross, then the tens. For example: 23 × 12: 3 × 2 = 6; 2 × 2 + 3 × 1 = 7; 2 × 1 = 2 → 276.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":8},"wordq-vertically-and-crosswise":{"id":"wordq-vertically-and-crosswise","kind":"wordq","src":"dictionary:vertically and crosswise#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “23 × 12: 3 × 2 = 6; 2 × 2 + 3 × 1 = 7; 2 × 1 = 2 → 276.”","opts":["vertically and crosswise","empty set","element"],"after":"vertically and crosswise: A way to multiply two-digit numbers in one line: the units, then the cross, then the tens."},"level":8},"formula-difference-of-squares":{"id":"formula-difference-of-squares","kind":"formula","src":"formula:difference-of-squares","title":"Difference of two squares","body":"a² − b² = (a + b)(a − b). Cut the L-shape and swing one piece round: a rectangle (a + b) by (a − b).","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Difference of two squares: 52 × 48, as 50² − 2².","opts":["2496","2497","2495"],"after":"50² = 2500, 2² = 4 · 2500 − 4 = 2496"},"level":8},"formula-why-difference-of-squares-0":{"id":"formula-why-difference-of-squares-0","kind":"formula-why","src":"formula:difference-of-squares#why0","title":"Why a² − b² = (a + b)(a − b)","body":"Take a square a by a and cut a small b by b square out of one corner. What is left is an L-shape with area a² − b².","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-why-difference-of-squares-1":{"id":"formula-why-difference-of-squares-1","kind":"formula-why","src":"formula:difference-of-squares#why1","title":"Why a² − b² = (a + b)(a − b)","body":"Slice the L into two rectangles and swing the smaller one round to the end of the bigger. Together they make one rectangle a + b long and a − b wide. So a² − b² = (a + b)(a − b) — and turned round, 52 × 48 = 50² − 2² = 2496.","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-story-difference-of-squares":{"id":"formula-story-difference-of-squares","kind":"formula-story","src":"formula:difference-of-squares#story","badge":{"id":"story","label":"A story"},"title":"The cinema seats","body":"A cinema has 43 rows of 37 seats. Ines wants the total before the film starts. — with Vesper and Ines.","art":"art/s-city.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-try-difference-of-squares":{"id":"formula-try-difference-of-squares","kind":"formula-try","src":"formula:difference-of-squares#gen0","title":"Difference of two squares — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"26² − 21² = ?","opts":["235","236","234"],"after":"a² − b² = (a + b)(a − b)"},"level":8},"formula-odd-numbers-square":{"id":"formula-odd-numbers-square","kind":"formula","src":"formula:odd-numbers-square","title":"Odd numbers make squares","body":"1 + 3 + 5 + … + (2n − 1) = n². Each new L of dots is the next odd number and makes the next square.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Odd numbers make squares: The first 6 odd numbers.","opts":["36","37","35"],"after":"1 + 3 + 5 + 7 + 9 + 11 · = 6 × 6 = 36"},"level":8},"formula-why-odd-numbers-square-0":{"id":"formula-why-odd-numbers-square-0","kind":"formula-why","src":"formula:odd-numbers-square#why0","title":"Why 1 + 3 + 5 + … + (2n − 1) = n²","body":"Start with one dot. Wrap 3 dots round two of its sides and you have a 2 by 2 square. Wrap 5 more round that and you have 3 by 3.","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-why-odd-numbers-square-1":{"id":"formula-why-odd-numbers-square-1","kind":"formula-why","src":"formula:odd-numbers-square#why1","title":"Why 1 + 3 + 5 + … + (2n − 1) = n²","body":"Each new L-shape is 2 dots longer than the last, so it is the next odd number — and each one grows the square by one. So the first n odd numbers always add up to n × n.","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-story-odd-numbers-square":{"id":"formula-story-odd-numbers-square","kind":"formula-story","src":"formula:odd-numbers-square#story","badge":{"id":"story","label":"A story"},"title":"Pebbles on the beach","body":"On the beach Pip lays pebbles in L-shapes round a first pebble: 1, then 3 round it, then 5, then 7, then 9. — with Suki and Pip.","art":"art/s-beach.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-try-odd-numbers-square":{"id":"formula-try-odd-numbers-square","kind":"formula-try","src":"formula:odd-numbers-square#gen0","title":"Odd numbers make squares — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"1 + 3 + 5 + … + 9 (the first 5 odd numbers). Total?","opts":["25","26","24"],"after":"1 + 3 + 5 + … + (2n − 1) = n²"},"level":8},"formula-factorial":{"id":"formula-factorial","kind":"formula","src":"formula:factorial","title":"Factorials","body":"n! = n × (n − 1) × … × 2 × 1, and 0! = 1. Each step down divides by one less. The last step, ÷ 1, leaves 0! = 1.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Factorials: How many ways can 5 friends stand in a line?","opts":["120","121","119"],"after":"5 choices, then 4, then 3, then 2, then 1 · 5! = 5 × 4 × 3 × 2 × 1 = 120"},"level":8},"formula-why-factorial-0":{"id":"formula-why-factorial-0","kind":"formula-why","src":"formula:factorial#why0","title":"Why n! = n × (n − 1) × … × 2 × 1, and 0! = 1","body":"n! counts the ways to put n different things in a row: n choices for the first place, n − 1 for the second, and so on down to 1 choice for the last. 4 books on a shelf can go in 4 × 3 × 2 × 1 = 24 orders.","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-why-factorial-1":{"id":"formula-why-factorial-1","kind":"formula-why","src":"formula:factorial#why1","title":"Why n! = n × (n − 1) × … × 2 × 1, and 0! = 1","body":"Every factorial holds the one below it — n! = n × (n − 1)! — so walking down the pattern means dividing: 4! ÷ 4 = 3!, and so on. One step past 1! is 1! ÷ 1 = 0!, which is why 0! = 1. It also cancels: 8! ÷ 6! = 8 × 7.","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-story-factorial":{"id":"formula-story-factorial","kind":"formula-story","src":"formula:factorial#story","badge":{"id":"story","label":"A story"},"title":"Books on the shelf","body":"Rafi has 4 new books for his shelf. He wants to try every different order before he chooses one. — with Rafi and Nova.","art":"art/s-library.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":8},"formula-try-factorial":{"id":"formula-try-factorial","kind":"formula-try","src":"formula:factorial#gen0","title":"Factorials — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"7! = ?","opts":["5040","5041","5039"],"after":"n! = n × (n − 1) × … × 2 × 1, and 0! = 1"},"level":8},"stone-vedic-nikhilam-100":{"src":"journey:vedic/nikhilam-100#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-nikhilam-100","kind":"stone","title":"Near 100, near 1000 — Nikhilam Navataścaramaṁ Daśataḥ","body":"The cross works around any base: 100, 1000, even 10 000. Near 100, the gaps multiply into the LAST TWO digits; near 1000, into the last three.","level":8},"stone-vedic-nikhilam-100-1":{"src":"journey:vedic/nikhilam-100#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-nikhilam-100-1","kind":"stone-step","title":"Near 100, near 1000 (2 of 3)","body":"97 × 96: gaps 3 and 4. 97 − 4 = 93 hundreds. 3 × 4 = 12. Answer 9312. Above: 104 × 107 is 104 + 7 = 111 hundreds and 4 × 7 = 28, so 11128.","level":8},"stone-vedic-nikhilam-100-2":{"src":"journey:vedic/nikhilam-100#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-nikhilam-100-2","kind":"stone-step","title":"Near 100, near 1000 (3 of 3)","body":"Why: (B − x)(B − y) = B(B − x − y) + xy, and (B + x)(B + y) = B(B + x + y) + xy. Same algebra, signs turned over. If the gaps multiply past the base, the extra carries.","level":8},"stone-try-vedic-nikhilam-100":{"src":"journey:vedic/nikhilam-100#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-nikhilam-100","kind":"stone-try","title":"Near 100, near 1000 — try it","play":{"q":"87 × 92 = ?","opts":["8004","13","8"],"after":"The same cross, bigger bases"},"level":8},"stone-vedic-urdhva":{"src":"journey:vedic/urdhva#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-urdhva","kind":"stone","title":"Vertically and crosswise — Ūrdhva-tiryagbhyām","body":"Write the two numbers one above the other. Work from the right: multiply the units vertically; then crosswise, and add; then the tens vertically. Carry as you go.","level":8},"stone-vedic-urdhva-1":{"src":"journey:vedic/urdhva#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-urdhva-1","kind":"stone-step","title":"Vertically and crosswise (2 of 4)","body":"23 × 41: units 3 × 1 = 3. Crosswise 2 × 1 + 3 × 4 = 14 — write 4, carry 1. Tens 2 × 4 = 8, and the 1 carried makes 9. Answer 943.","level":8},"stone-vedic-urdhva-2":{"src":"journey:vedic/urdhva#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-urdhva-2","kind":"stone-step","title":"Vertically and crosswise (3 of 4)","body":"Why: (10a + b)(10c + d) = 100ac + 10(ad + bc) + bd. The crosswise step is the two pieces that both land in the tens column.","level":8},"stone-vedic-urdhva-3":{"src":"journey:vedic/urdhva#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-urdhva-3","kind":"stone-step","title":"Vertically and crosswise (4 of 4)","body":"Three digits make five columns: vertical, crosswise, a \"star\" of three pairs in the middle, crosswise, vertical. It is the same idea, one column at a time (you meet it on the Stretch level).","level":8},"stone-try-vedic-urdhva":{"src":"journey:vedic/urdhva#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-urdhva","kind":"stone-try","title":"Vertically and crosswise — try it","play":{"q":"76 × 35 = ?","opts":["2660","30","53"],"after":"Any two numbers, one line"},"level":8},"stone-vedic-check":{"src":"journey:vedic/check#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-check","kind":"stone","title":"The product of the sums — Guṇitasamuccayaḥ","body":"Add up a number's digits, and keep adding until one digit is left: that is its digit root. 47 → 4 + 7 = 11 → 1 + 1 = 2.","level":8},"stone-vedic-check-1":{"src":"journey:vedic/check#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-check-1","kind":"stone-step","title":"The product of the sums (2 of 4)","body":"To check a multiplication, multiply the digit roots of the two numbers, and find the digit root of that. It must match the digit root of the answer. 47 × 23 = 1081? Roots 2 and 5; 2 × 5 = 10 → 1. And 1081 → 10 → 1. It matches, so it could be right.","level":8},"stone-vedic-check-2":{"src":"journey:vedic/check#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-check-2","kind":"stone-step","title":"The product of the sums (3 of 4)","body":"Why: a digit root is the remainder when you divide by 9 (with 9 for none left). Every 10 is 9 + 1, so 10, 100, 1000 all leave 1 — and remainders multiply just like the numbers do.","level":8},"stone-vedic-check-3":{"src":"journey:vedic/check#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-check-3","kind":"stone-step","title":"The product of the sums (4 of 4)","body":"Be careful: if the check fails, the answer is certainly wrong. If it passes, the answer COULD be right — swapping two digits, or being out by 9, slips past it.","level":8},"stone-try-vedic-check":{"src":"journey:vedic/check#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-check","kind":"stone-try","title":"The product of the sums — try it","play":{"q":"Someone says 93 × 43 = 4006. What does the nines check say?","opts":["Must be wrong","Could be right"],"after":"Checking with digit sums"},"level":8}};
